#[inline(always)]
fn g(s: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    s[a] = s[a].wrapping_add(s[b]).wrapping_add(x);
    s[d] = (s[d] ^ s[a]).rotate_right(16);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_right(12);
    s[a] = s[a].wrapping_add(s[b]).wrapping_add(y);
    s[d] = (s[d] ^ s[a]).rotate_right(8);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_right(7);
}

fn compress(cv: &[u32; 8], block: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut s = [
        cv[0], cv[1], cv[2], cv[3], cv[4], cv[5], cv[6], cv[7], IV[0], IV[1], IV[2], IV[3],
        counter as u32, (counter >> 32) as u32, block_len, flags,
    ];
    let mut m = *block;
    for r in 0..7 {
        g(&mut s, 0, 4, 8, 12, m[0], m[1]);
        g(&mut s, 1, 5, 9, 13, m[2], m[3]);
        g(&mut s, 2, 6, 10, 14, m[4], m[5]);
        g(&mut s, 3, 7, 11, 15, m[6], m[7]);
        g(&mut s, 0, 5, 10, 15, m[8], m[9]);
        g(&mut s, 1, 6, 11, 12, m[10], m[11]);
        g(&mut s, 2, 7, 8, 13, m[12], m[13]);
        g(&mut s, 3, 4, 9, 14, m[14], m[15]);
        if r < 6 {
            let mut p = [0u32; 16];
            for i in 0..16 {
                p[i] = m[MSG_PERMUTATION[i]];
            }
            m = p;
        }
    }
    for i in 0..8 {
        s[i] ^= s[i + 8];
        s[i + 8] ^= cv[i];
    }
    s
}

fn words(block: &[u8]) -> [u32; 16] {
    let mut buf = [0u8; 64];
    buf[..block.len()].copy_from_slice(block);
    let mut w = [0u32; 16];
    for i in 0..16 {
        w[i] = u32::from_le_bytes([buf[4 * i], buf[4 * i + 1], buf[4 * i + 2], buf[4 * i + 3]]);
    }
    w
}

fn first8(s: &[u32; 16]) -> [u32; 8] {
    let mut o = [0u32; 8];
    o.copy_from_slice(&s[..8]);
    o
}

struct Output {
    cv: [u32; 8],
    block: [u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
}

impl Output {
    fn chaining_value(&self) -> [u32; 8] {
        first8(&compress(&self.cv, &self.block, self.counter, self.block_len, self.flags))
    }
    fn root_bytes(&self) -> [u8; 32] {
        let s = compress(&self.cv, &self.block, self.counter, self.block_len, self.flags | ROOT);
        let mut out = [0u8; 32];
        for i in 0..8 {
            out[4 * i..4 * i + 4].copy_from_slice(&s[i].to_le_bytes());
        }
        out
    }
}

fn chunk_output(chunk: &[u8], counter: u64) -> Output {
    let mut cv = IV;
    let nblocks = if chunk.is_empty() { 1 } else { (chunk.len() + BLOCK_LEN - 1) / BLOCK_LEN };
    for i in 0..nblocks {
        let start = i * BLOCK_LEN;
        let end = (start + BLOCK_LEN).min(chunk.len());
        let block = &chunk[start.min(chunk.len())..end];
        let mut flags = 0;
        if i == 0 {
            flags |= CHUNK_START;
        }
        if i == nblocks - 1 {
            flags |= CHUNK_END;
            return Output { cv, block: words(block), counter, block_len: block.len() as u32, flags };
        }
        cv = first8(&compress(&cv, &words(block), counter, BLOCK_LEN as u32, flags));
    }
    unreachable!()
}

fn parent_output(left: &[u32; 8], right: &[u32; 8]) -> Output {
    let mut block = [0u32; 16];
    block[..8].copy_from_slice(left);
    block[8..].copy_from_slice(right);
    Output { cv: IV, block, counter: 0, block_len: BLOCK_LEN as u32, flags: PARENT }
}

pub fn hash(data: &[u8]) -> [u8; 32] {
    let nchunks = if data.is_empty() { 1 } else { (data.len() + CHUNK_LEN - 1) / CHUNK_LEN };
    let mut stack: Vec<[u32; 8]> = Vec::new();
    for ci in 0..nchunks {
        let start = ci * CHUNK_LEN;
        let end = (start + CHUNK_LEN).min(data.len());
        let out = chunk_output(&data[start.min(data.len())..end], ci as u64);
        if ci == nchunks - 1 {
            let mut out = out;
            while let Some(left) = stack.pop() {
                let right = out.chaining_value();
                out = parent_output(&left, &right);
            }
            return out.root_bytes();
        }
        let mut cv = out.chaining_value();
        let mut total = (ci + 1) as u64;
        while total & 1 == 0 {
            let left = stack.pop().unwrap();
            cv = parent_output(&left, &cv).chaining_value();
            total >>= 1;
        }
        stack.push(cv);
    }
    unreachable!()
}

pub fn hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

pub fn hash_hex(data: &[u8]) -> String {
    hex(&hash(data))
}
EOF
