}

#[derive(serde::Deserialize)]
struct Frontmatter {
    name: Option<String>,
}

enum State {
    Initial,
    Question { text: String, start: usize },
    Answer { question: String, text: String, start: usize },
    Cloze { text: String, start: usize },
}

fn parse_error(msg: &str, file: &Path, line: usize) -> Error {
    Error::Msg(format!("Parse error: {}. Location: {}:{}", msg, file.display(), line))
}

/// Split a cloze card's raw text into clean text and deletions (byte ranges, inclusive).
pub fn parse_cloze_text(text: &str) -> (String, Vec<(usize, usize)>) {
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    let mut clean = String::new();
    let mut deletions = Vec::new();
    let mut start: Option<usize> = None;
    let mut i = 0;
    while i < n {
        let c = chars[i];
        if c == '\\' && i + 1 < n && (chars[i + 1] == '[' || chars[i + 1] == ']') {
            clean.push(chars[i + 1]);
            i += 2;
            continue;
        }
        if c == '!' && i + 1 < n && chars[i + 1] == '[' {
            clean.push('!');
            clean.push('[');
            i += 2;
            while i < n && chars[i] != ']' {
                clean.push(chars[i]);
                i += 1;
            }
            if i < n {
                clean.push(']');
                i += 1;
            }
            continue;
        }
        if c == '[' {
            start = Some(clean.len());
            i += 1;
            continue;
        }
        if c == ']' {
            if let Some(s) = start.take() {
                deletions.push((s, clean.len().wrapping_sub(1)));
            }
            i += 1;
            continue;
        }
        clean.push(c);
        i += 1;
    }
    (clean, deletions)
}

fn append_line(buf: &mut String, line: &str) {
    buf.push('\n');
    buf.push_str(line);
}

pub fn parse_deck(content: &str, file: &Path, rel_dir: &Path) -> Result<Vec<Card>, Error> {
    let all_lines: Vec<&str> = content.lines().collect();
    let mut deck_name = file
        .file_stem()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_default();
    let mut body_start = 0;
    if let Some(first) = all_lines.first() {
        if first.trim() == "---" {
            let mut close = None;
            for (j, l) in all_lines.iter().enumerate().skip(1) {
                if l.trim() == "---" {
                    close = Some(j);
                    break;
                }
            }
            let close = match close {
                Some(c) => c,
                None => {
                    return Err(Error::Msg(
                        "Frontmatter opening '---' found but no closing '---'".to_string(),
                    ))
                }
            };
            let toml_src = all_lines[1..close].join("\n");
            let fm: Frontmatter = toml::from_str(&toml_src).map_err(|e| {
                Error::Msg(format!("Failed to parse TOML frontmatter: {}", e))
            })?;
            if let Some(n) = fm.name {
                deck_name = n;
            }
            body_start = close + 1;
        }
    }
    let lines = &all_lines[body_start..];
    let mut cards = Vec::new();
    let mut state = State::Initial;

    let finish = |state: State, end: usize, cards: &mut Vec<Card>| -> Result<(), Error> {
        match state {
            State::Initial => Ok(()),
            State::Question { .. } => unreachable!(),
            State::Answer { question, text, start } => {
                cards.push(Card::new(
                    &deck_name,
                    file,
                    rel_dir,
                    start,
                    end,
                    CardContent::Basic {
                        question: question.trim().to_string(),
                        answer: text.trim().to_string(),
                    },
                ));
                Ok(())
            }
            State::Cloze { text, start } => {
                let trimmed = text.trim();
                let (clean, deletions) = parse_cloze_text(trimmed);
                if deletions.is_empty() {
                    return Err(parse_error(
                        "Cloze card must contain at least one cloze deletion",
                        file,
                        start + 1,
                    ));
                }
                for (s, e) in deletions {
                    cards.push(Card::new(
                        &deck_name,
                        file,
                        rel_dir,
                        start,
                        end,
                        CardContent::Cloze { text: clean.clone(), start: s, end: e },
                    ));
                }
                Ok(())
            }
        }
    };

    for (i, line) in lines.iter().enumerate() {
        if let Some(rest) = line.strip_prefix("Q:") {
            state = match state {
                State::Initial => State::Question { text: rest.to_string(), start: i },
                State::Question { .. } => {
                    return Err(parse_error("New question without answer", file, i + 1))
                }
                s @ (State::Answer { .. } | State::Cloze { .. }) => {
                    finish(s, i, &mut cards)?;
                    State::Question { text: rest.to_string(), start: i }
                }
            };
        } else if let Some(rest) = line.strip_prefix("A:") {
            state = match state {
                State::Initial => {
                    return Err(parse_error("Found answer tag without a question", file, i + 1))
                }
                State::Question { text, start } => {
                    State::Answer { question: text, text: rest.to_string(), start }
                }
                State::Answer { .. } => {
                    return Err(parse_error(
                        "Found answer tag while reading an answer",
                        file,
                        i + 1,
                    ))
                }
                State::Cloze { .. } => {
                    return Err(parse_error(
                        "Found answer tag while reading a cloze card",
                        file,
                        i + 1,
                    ))
                }
            };
        } else if let Some(rest) = line.strip_prefix("C:") {
            state = match state {
                State::Initial => State::Cloze { text: rest.to_string(), start: i },
                State::Question { .. } => {
                    return Err(parse_error(
                        "Found cloze tag while reading a question",
                        file,
                        i + 1,
                    ))
                }
                s @ (State::Answer { .. } | State::Cloze { .. }) => {
                    finish(s, i, &mut cards)?;
                    State::Cloze { text: rest.to_string(), start: i }
                }
            };
        } else if line.trim() == "---" {
            state = match state {
                State::Initial => State::Initial,
                State::Question { .. } => {
                    return Err(parse_error(
                        "Found flashcard separator while reading a question",
                        file,
                        i + 1,
                    ))
                }
                s @ (State::Answer { .. } | State::Cloze { .. }) => {
                    finish(s, i, &mut cards)?;
                    State::Initial
                }
            };
        } else {
            match &mut state {
                State::Initial => {}
                State::Question { text, .. } => append_line(text, line),
                State::Answer { text, .. } => append_line(text, line),
                State::Cloze { text, .. } => append_line(text, line),
            }
        }
    }
    let last = lines.len().saturating_sub(1);
    match state {
        State::Question { .. } => {
            return Err(parse_error(
                "File ended while reading a question without an answer",
                file,
                last + 1,
            ))
        }
        s => finish(s, last, &mut cards)?,
    }
    Ok(cards)
}
