impl Connection {
    pub fn open(path: &str) -> Result<Connection, Error> {
        let c = CString::new(path).unwrap();
        let mut db: *mut sqlite3 = ptr::null_mut();
        let rc = unsafe {
            sqlite3_open_v2(
                c.as_ptr(),
                &mut db,
                SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_URI | SQLITE_OPEN_NOMUTEX,
                ptr::null(),
            )
        };
        if rc != SQLITE_OK {
            let (code, msg) = if db.is_null() {
                (rc, "out of memory".to_string())
            } else {
                let code = unsafe { sqlite3_extended_errcode(db) };
                let msg = unsafe { CStr::from_ptr(sqlite3_errmsg(db)) }.to_string_lossy().to_string();
                unsafe { sqlite3_close(db) };
                (code, msg)
            };
