        let c = CString::new(sql).unwrap();
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let rc = unsafe { sqlite3_prepare_v2(self.db, c.as_ptr(), -1, &mut stmt, ptr::null_mut()) };
        if rc != SQLITE_OK {
            return Err(self.err());
        }
        for (i, p) in params.iter().enumerate() {
            let idx = (i + 1) as c_int;
            let rc = unsafe {
                match p {
                    Value::Null => sqlite3_bind_null(stmt, idx),
                    Value::Int(n) => sqlite3_bind_int64(stmt, idx, *n),
                    Value::Real(f) => sqlite3_bind_double(stmt, idx, *f),
                    Value::Text(s) => sqlite3_bind_text(
                        stmt,
                        idx,
                        s.as_ptr() as *const c_char,
                        s.len() as c_int,
                        SQLITE_TRANSIENT,
                    ),
                }
            };
            if rc != SQLITE_OK {
                unsafe { sqlite3_finalize(stmt) };
                return Err(self.err());
            }
        }
        Ok(stmt)
    }

    pub fn execute(&self, sql: &str, params: &[Value]) -> Result<(), Error> {
        let stmt = self.prepare(sql, params)?;
        loop {
            let rc = unsafe { sqlite3_step(stmt) };
            if rc == SQLITE_ROW {
                continue;
            }
            unsafe { sqlite3_finalize(stmt) };
            if rc == SQLITE_DONE {
                return Ok(());
            }
            return Err(self.err());
        }
    }

    pub fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.db) }
    }

    pub fn query(&self, sql: &str, params: &[Value]) -> Result<Vec<Row>, Error> {
        let stmt = self.prepare(sql, params)?;
        let mut rows = Vec::new();
        loop {
            let rc = unsafe { sqlite3_step(stmt) };
            if rc == SQLITE_ROW {
                let n = unsafe { sqlite3_column_count_safe(stmt) };
