    fn sqlite3_column_count(stmt: *mut sqlite3_stmt) -> c_int;
}

unsafe fn sqlite3_column_count_safe(stmt: *mut sqlite3_stmt) -> usize {
    sqlite3_column_count(stmt) as usize
}

impl Drop for Connection {
    fn drop(&mut self) {
        unsafe {
            sqlite3_close(self.db);
        }
    }
