        normalize(&rel_dir.join(src))
    }
}

pub fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 + 0 {
            let h = (b[i + 1] as char).to_digit(16);
            let l = (b[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (h, l) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

fn media_exists(root: &Path, src: &str, rel_dir: &Path) -> bool {
    let check = |s: &str| -> bool {
        match resolve_media(s, rel_dir) {
            Some(p) => {
                if p.as_os_str().is_empty() {
                    return root.join(&p).exists();
                }
                root.join(&p).exists()
            }
            None => false,
        }
    };
    if check(src) {
        return true;
    }
    let decoded = percent_decode(src);
    check(decoded.trim())
}

pub fn card_markdown_sources(card: &Card) -> Vec<&str> {
    match &card.content {
        CardContent::Basic { question, answer } => vec![question.as_str(), answer.as_str()],
        CardContent::Cloze { text, .. } => vec![text.as_str()],
    }
}

pub fn load(directory: Option<&str>) -> Result<Collection> {
    let root = resolve_dir(directory)?;
    let db_path = root.join("hashcards.db");
    let db = Database::open(&db_path.to_string_lossy())?;
    let mut entries = Vec::new();
    walk(&root, &mut entries)?;
    let mut cards = Vec::new();
    let mut seen = HashSet::new();
    for path in entries {
        if path.extension().map(|e| e == "md").unwrap_or(false) && path.is_file() {
            let canonical = fs::canonicalize(&path)?;
            let rel = canonical.strip_prefix(&root).map_err(|e| {
                Error::Msg(format!("Strip prefix error: {:#?}", e))
            })?;
            let rel_dir = rel.parent().map(|p| p.to_path_buf()).unwrap_or_default();
            let content = fs::read_to_string(&path)?;
            let deck_cards = parse_deck(&content, &path, &rel_dir)?;
            for c in deck_cards {
                if seen.insert(c.hash.clone()) {
                    cards.push(c);
                }
            }
        }
    }
    // Check media references.
    let mut missing: BTreeSet<(String, PathBuf, usize)> = BTreeSet::new();
    for card in &cards {
        for src in card_markdown_sources(card) {
            for dest in markdown::image_destinations(src) {
                if !media_exists(&root, &dest, &card.rel_dir) {
                    missing.insert((percent_decode(&dest), card.file_path.clone(), card.line_start));
                }
            }
        }
    }
    if !missing.is_empty() {
        let mut msg = String::from("Missing media files referenced in cards:\n");
        for (p, f, l) in &missing {
            msg.push_str(&format!("  - {} (referenced in {}:{})\n", p, f.display(), l));
        }
        return Err(Error::Msg(msg));
    }
    cards.sort_by(|a, b| a.hash.cmp(&b.hash));
    let macros = load_macros(&root)?;
    Ok(Collection { root, db, cards, macros })
}

pub fn load_macros(root: &Path) -> Result<Vec<(String, String)>> {
    let path = root.join("macros.tex");
    let mut out = Vec::new();
    if path.exists() {
        let content = fs::read_to_string(&path)?;
        for line in content.lines() {
            if line.trim().starts_with('%') {
                continue;
            }
            if let Some((name, def)) = line.split_once(' ') {
                out.push((name.to_string(), def.to_string()));
            }
        }
    }
    Ok(out)
}
