//! FSRS scheduling algorithm.

const W: [f64; 19] = [
    0.40255, 1.18385, 3.173, 15.69105, 7.1949, 0.5345, 1.4604, 0.0046, 1.54575, 0.1192, 1.01925,
    1.9395, 0.11, 0.29605, 2.2698, 0.2315, 2.9898, 0.51655, 0.6621,
];
const F: f64 = 19.0 / 81.0;
const DECAY: f64 = -0.5;
const DESIRED_RETENTION: f64 = 0.9;
const MAX_INTERVAL: f64 = 256.0;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Grade {
    Forgot,
    Hard,
    Good,
    Easy,
}

impl Grade {
    pub fn value(self) -> f64 {
        match self {
            Grade::Forgot => 1.0,
            Grade::Hard => 2.0,
            Grade::Good => 3.0,
            Grade::Easy => 4.0,
        }
    }
    pub fn db_name(self) -> &'static str {
        match self {
            Grade::Forgot => "forgot",
            Grade::Hard => "hard",
            Grade::Good => "good",
            Grade::Easy => "easy",
        }
    }
}

fn retrievability(t: f64, s: f64) -> f64 {
    (1.0 + F * (t / s)).powf(DECAY)
}

fn initial_stability(g: Grade) -> f64 {
    match g {
        Grade::Forgot => W[0],
        Grade::Hard => W[1],
        Grade::Good => W[2],
        Grade::Easy => W[3],
    }
}

fn clamp_d(d: f64) -> f64 {
    d.max(1.0).min(10.0)
}

fn initial_difficulty(g: f64) -> f64 {
    W[4] - (W[5] * (g - 1.0)).exp() + 1.0
}

fn new_difficulty(d: f64, g: Grade) -> f64 {
    let g = g.value();
    let dpp = d + (-W[6] * (g - 3.0)) * ((10.0 - d) / 9.0);
    clamp_d(W[7] * initial_difficulty(4.0) + (1.0 - W[7]) * dpp)
}

fn stability_recall(d: f64, s: f64, r: f64, g: Grade) -> f64 {
    let hp = if g == Grade::Hard { W[15] } else { 1.0 };
    let eb = if g == Grade::Easy { W[16] } else { 1.0 };
    s * ((11.0 - d) * s.powf(-W[9]) * ((W[10] * (1.0 - r)).exp() - 1.0) * hp * eb * W[8].exp()
        + 1.0)
}

fn stability_forget(d: f64, s: f64, r: f64) -> f64 {
    W[11] * (d.powf(-W[12]) * ((s + 1.0).powf(W[13]) - 1.0) * (W[14] * (1.0 - r)).exp())
}

pub fn interval(s: f64) -> f64 {
    s / F * (DESIRED_RETENTION.powf(1.0 / DECAY) - 1.0)
}

pub fn interval_days(raw: f64) -> i64 {
    raw.round().max(1.0).min(MAX_INTERVAL) as i64
}

/// Compute new (stability, difficulty) given optional previous (stability,
/// difficulty) and the elapsed days since the last review.
pub fn review(prev: Option<(f64, f64)>, elapsed_days: f64, g: Grade) -> (f64, f64) {
    match prev {
        None => (initial_stability(g), clamp_d(initial_difficulty(g.value()))),
        Some((s, d)) => {
            let r = retrievability(elapsed_days, s);
            let ns = if g == Grade::Forgot {
                stability_forget(d, s, r)
            } else {
                stability_recall(d, s, r, g)
            };
            (ns, new_difficulty(d, g))
        }
    }
}
