//! A small HTTP/1.1 server.

use std::io::{BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream, ToSocketAddrs};
use std::os::unix::io::FromRawFd;

pub struct Request {
    pub method: String,
    pub path: String,
    pub query: Option<String>,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
}

impl Request {
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }
}

pub struct Response {
    pub status: u16,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
    /// Whether the content-length header is known up-front (non-empty body).
    pub sized: bool,
    /// Drop the connection without sending anything.
    pub abort: bool,
}

impl Response {
    pub fn new(status: u16, headers: Vec<(&str, &str)>, body: Vec<u8>) -> Response {
        let sized = !body.is_empty();
        Response {
            status,
            headers: headers.into_iter().map(|(k, v)| (k.to_string(), v.to_string())).collect(),
            body,
            sized,
            abort: false,
        }
    }
    pub fn empty(status: u16, headers: Vec<(&str, &str)>) -> Response {
        Response::new(status, headers, Vec::new())
    }
    pub fn abort() -> Response {
        Response { status: 500, headers: vec![], body: vec![], sized: false, abort: true }
    }
}

fn reason(status: u16) -> &'static str {
    match status {
        100 => "Continue",
        200 => "OK",
        303 => "See Other",
        400 => "Bad Request",
        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Payload Too Large",
        415 => "Unsupported Media Type",
        422 => "Unprocessable Entity",
        500 => "Internal Server Error",
        _ => "Unknown",
    }
}

pub fn http_date() -> String {
    chrono::Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()
}

/// Bind a listening socket with SO_REUSEADDR, like tokio/mio do.
pub fn bind(host: &str, port: u16) -> std::io::Result<TcpListener> {
    let addrs: Vec<SocketAddr> = (host, port).to_socket_addrs()?.collect();
    let mut last_err = None;
    for addr in addrs {
        match bind_one(&addr) {
            Ok(l) => return Ok(l),
            Err(e) => last_err = Some(e),
        }
    }
    Err(last_err.unwrap_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::InvalidInput, "could not resolve to any address")
    }))
}

fn bind_one(addr: &SocketAddr) -> std::io::Result<TcpListener> {
    unsafe {
        let domain = if addr.is_ipv4() { libc::AF_INET } else { libc::AF_INET6 };
        let fd = libc::socket(domain, libc::SOCK_STREAM | libc::SOCK_CLOEXEC, 0);
        if fd < 0 {
            return Err(std::io::Error::last_os_error());
        }
        let one: libc::c_int = 1;
        libc::setsockopt(
            fd,
            libc::SOL_SOCKET,
            libc::SO_REUSEADDR,
            &one as *const _ as *const libc::c_void,
            std::mem::size_of::<libc::c_int>() as libc::socklen_t,
        );
        let rc = match addr {
            SocketAddr::V4(a) => {
                let mut sin: libc::sockaddr_in = std::mem::zeroed();
                sin.sin_family = libc::AF_INET as libc::sa_family_t;
                sin.sin_port = a.port().to_be();
                sin.sin_addr = libc::in_addr { s_addr: u32::from_ne_bytes(a.ip().octets()) };
                libc::bind(
                    fd,
                    &sin as *const _ as *const libc::sockaddr,
                    std::mem::size_of::<libc::sockaddr_in>() as libc::socklen_t,
                )
            }
            SocketAddr::V6(a) => {
                let mut sin6: libc::sockaddr_in6 = std::mem::zeroed();
                sin6.sin6_family = libc::AF_INET6 as libc::sa_family_t;
                sin6.sin6_port = a.port().to_be();
                sin6.sin6_addr = libc::in6_addr { s6_addr: a.ip().octets() };
                sin6.sin6_flowinfo = a.flowinfo();
                sin6.sin6_scope_id = a.scope_id();
                libc::bind(
                    fd,
                    &sin6 as *const _ as *const libc::sockaddr,
                    std::mem::size_of::<libc::sockaddr_in6>() as libc::socklen_t,
                )
            }
        };
        if rc < 0 {
            let e = std::io::Error::last_os_error();
            libc::close(fd);
            return Err(e);
        }
        if libc::listen(fd, 1024) < 0 {
            let e = std::io::Error::last_os_error();
            libc::close(fd);
            return Err(e);
        }
        Ok(TcpListener::from_raw_fd(fd))
    }
}

enum ReadResult {
    Req(Request, bool /*http10*/),
    Closed,
    Bad,
}

fn read_request(reader: &mut BufReader<TcpStream>, stream: &mut TcpStream) -> ReadResult {
    let mut line = String::new();
    // Skip leading empty lines.
    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => return ReadResult::Closed,
            Ok(_) => {}
            Err(_) => return ReadResult::Closed,
        }
        if line.trim_end_matches(['\r', '\n']).is_empty() {
            continue;
        }
        break;
    }
    let reqline = line.trim_end_matches(['\r', '\n']).to_string();
    let parts: Vec<&str> = reqline.split(' ').collect();
    if parts.len() != 3 {
        return ReadResult::Bad;
    }
    let method = parts[0].to_string();
    let target = parts[1].to_string();
    let version = parts[2];
    let http10 = match version {
        "HTTP/1.1" => false,
        "HTTP/1.0" => true,
        _ => return ReadResult::Bad,
    };
    let mut headers = Vec::new();
    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => return ReadResult::Closed,
            Ok(_) => {}
            Err(_) => return ReadResult::Closed,
        }
        let l = line.trim_end_matches(['\r', '\n']);
        if l.is_empty() {
            break;
        }
        match l.split_once(':') {
            Some((k, v)) => headers.push((k.trim().to_string(), v.trim().to_string())),
            None => return ReadResult::Bad,
        }
    }
    let mut req = Request { method, path: String::new(), query: None, headers, body: Vec::new() };
    // Target: strip scheme/authority if absolute.
    let mut t = target.as_str();
    if let Some(rest) = t.strip_prefix("http://").or_else(|| t.strip_prefix("https://")) {
        t = match rest.find('/') {
            Some(i) => &rest[i..],
            None => "/",
        };
    }
    let t = t.split('#').next().unwrap_or("");
    match t.split_once('?') {
        Some((p, q)) => {
            req.path = p.to_string();
            req.query = Some(q.to_string());
        }
        None => req.path = t.to_string(),
    }
    if req
        .header("Expect")
        .map(|v| v.eq_ignore_ascii_case("100-continue"))
        .unwrap_or(false)
    {
        let _ = stream.write_all(b"HTTP/1.1 100 Continue\r\n\r\n");
    }
    let chunked = req
        .header("Transfer-Encoding")
        .map(|v| v.to_ascii_lowercase().contains("chunked"))
        .unwrap_or(false);
    if chunked {
        let mut body = Vec::new();
        loop {
            line.clear();
            if reader.read_line(&mut line).unwrap_or(0) == 0 {
                return ReadResult::Closed;
            }
            let size_str = line.trim().split(';').next().unwrap_or("").trim().to_string();
            let size = match usize::from_str_radix(&size_str, 16) {
                Ok(s) => s,
                Err(_) => return ReadResult::Bad,
            };
            if size == 0 {
                // trailers
                loop {
                    line.clear();
                    if reader.read_line(&mut line).unwrap_or(0) == 0 {
                        break;
                    }
                    if line.trim().is_empty() {
                        break;
                    }
                }
                break;
            }
            let mut chunk = vec![0u8; size];
            if reader.read_exact(&mut chunk).is_err() {
                return ReadResult::Closed;
            }
            body.extend_from_slice(&chunk);
            line.clear();
            let _ = reader.read_line(&mut line);
        }
        req.body = body;
    } else if let Some(cl) = req.header("Content-Length") {
        let n: usize = match cl.trim().parse() {
            Ok(n) => n,
            Err(_) => return ReadResult::Bad,
        };
        let mut body = vec![0u8; n];
        if reader.read_exact(&mut body).is_err() {
            return ReadResult::Closed;
        }
        req.body = body;
    }
    ReadResult::Req(req, http10)
}

fn wants_close(req: &Request, http10: bool) -> (bool, Option<&'static str>) {
    let conn = req.header("Connection").map(|v| v.to_ascii_lowercase());
    let has = |tok: &str| -> bool {
        conn.as_ref()
            .map(|v| v.split(',').any(|t| t.trim() == tok))
            .unwrap_or(false)
    };
    if http10 {
        if has("keep-alive") {
            (false, Some("keep-alive"))
        } else {
            (true, None)
        }
    } else if has("close") {
        (true, Some("close"))
    } else {
        (false, None)
    }
}

pub fn write_response(stream: &mut TcpStream, resp: &Response, http10: bool, conn_hdr: Option<&str>, head: bool) -> std::io::Result<()> {
    let mut out = Vec::new();
    let ver = if http10 { "HTTP/1.0" } else { "HTTP/1.1" };
    out.extend_from_slice(format!("{} {} {}\r\n", ver, resp.status, reason(resp.status)).as_bytes());
    for (k, v) in &resp.headers {
        out.extend_from_slice(format!("{}: {}\r\n", k, v).as_bytes());
    }
    if resp.sized {
        out.extend_from_slice(format!("content-length: {}\r\n", resp.body.len()).as_bytes());
        if let Some(c) = conn_hdr {
            out.extend_from_slice(format!("connection: {}\r\n", c).as_bytes());
        }
    } else {
        if let Some(c) = conn_hdr {
            out.extend_from_slice(format!("connection: {}\r\n", c).as_bytes());
        }
        out.extend_from_slice(format!("content-length: {}\r\n", resp.body.len()).as_bytes());
    }
    out.extend_from_slice(format!("date: {}\r\n\r\n", http_date()).as_bytes());
    if !head {
        out.extend_from_slice(&resp.body);
    }
    stream.write_all(&out)?;
    stream.flush()
}

/// What to do after a response has been written.
pub enum After {
    Continue,
    Exit(i32),
}

pub fn serve<H>(listener: TcpListener, handler: H)
where
    H: Fn(&Request) -> (Response, After) + Send + Sync + 'static,
{
    let handler = std::sync::Arc::new(handler);
    for stream in listener.incoming() {
        let stream = match stream {
            Ok(s) => s,
            Err(_) => continue,
        };
        let handler = handler.clone();
        std::thread::spawn(move || {
            handle_connection(stream, &*handler);
        });
    }
}

fn handle_connection<H>(stream: TcpStream, handler: &H)
where
    H: Fn(&Request) -> (Response, After),
{
    let _ = stream.set_nodelay(true);
    let mut write_stream = match stream.try_clone() {
        Ok(s) => s,
        Err(_) => return,
    };
    let mut reader = BufReader::new(stream);
    loop {
        match read_request(&mut reader, &mut write_stream) {
            ReadResult::Closed => return,
            ReadResult::Bad => {
                let resp = Response::empty(400, vec![]);
                let _ = write_response(&mut write_stream, &resp, false, Some("close"), false);
                return;
            }
            ReadResult::Req(req, http10) => {
                let (close, conn_hdr) = wants_close(&req, http10);
                let head = req.method == "HEAD";
                let (resp, after) = handler(&req);
                if resp.abort {
                    let _ = write_stream.shutdown(std::net::Shutdown::Both);
                    return;
                }
                let _ = write_response(&mut write_stream, &resp, http10, conn_hdr, head);
                if let After::Exit(code) = after {
                    let _ = write_stream.shutdown(std::net::Shutdown::Write);
                    std::process::exit(code);
                }
                if close {
                    let _ = write_stream.shutdown(std::net::Shutdown::Both);
                    return;
                }
            }
        }
    }
}
