}

fn handle(state: &Arc<Mutex<State>>, req: &Request) -> (Response, After) {
    let path = req.path.as_str();
    let is_get = req.method == "GET" || req.method == "HEAD";
    let static_asset = |ct: &str, body: &[u8], cache: bool| -> (Response, After) {
        if !is_get {
            return (method_not_allowed("GET,HEAD"), After::Continue);
        }
        let mut headers = vec![("content-type", ct)];
        if cache {
            headers.push(("cache-control", CACHE));
        }
        (Response::new(200, headers, body.to_vec()), After::Continue)
    };
    match path {
        "/" => {
            if is_get {
                (get_root(state), After::Continue)
            } else if req.method == "POST" {
                post_root(state, req)
            } else {
                (method_not_allowed("GET,HEAD,POST"), After::Continue)
            }
        }
        "/style.css" => static_asset("text/css", STYLE_CSS, true),
        "/katex/katex.css" => static_asset("text/css", KATEX_CSS, true),
        "/katex/katex.js" => static_asset("text/javascript", KATEX_JS, true),
        "/katex/mhchem.js" => static_asset("text/javascript", MHCHEM_JS, true),
        "/script.js" => {
            let js = match state.lock() {
                Ok(s) => s.macros_js.clone(),
                Err(_) => return (Response::abort(), After::Continue),
            };
            static_asset("text/javascript", js.as_bytes(), false)
        }
        _ => {
            if let Some(name) = path.strip_prefix("/katex/fonts/") {
                if name.is_empty() {
                    return (not_found_html(), After::Continue);
                }
                if !is_get {
                    return (method_not_allowed("GET,HEAD"), After::Continue);
                }
                let name = percent_decode(name);
                for (n, data) in FONTS {
                    if *n == name {
                        return (
                            Response::new(
                                200,
                                vec![("content-type", "font/woff2"), ("cache-control", CACHE)],
                                data.to_vec(),
                            ),
                            After::Continue,
                        );
                    }
                }
                return (
                    Response::new(
                        404,
                        vec![("content-type", "text/plain"), ("cache-control", "no-cache")],
                        b"Not Found".to_vec(),
                    ),
                    After::Continue,
                );
            }
            if let Some(rest) = path.strip_prefix("/file/") {
                if rest.is_empty() {
                    return (not_found_html(), After::Continue);
                }
                if !is_get {
                    return (method_not_allowed("GET,HEAD"), After::Continue);
                }
                let root = match state.lock() {
                    Ok(s) => s.root.clone(),
                    Err(_) => return (Response::abort(), After::Continue),
                };
                return (serve_file(&root, &percent_decode(rest)), After::Continue);
            }
            (not_found_html(), After::Continue)
        }
    }
}

fn mime_for(path: &str) -> &'static str {
    let ext = std::path::Path::new(path)
        .extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    match ext.as_str() {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "ogg" => "audio/ogg",
        "mp4" => "video/mp4",
        "webm" => "video/webm",
        _ => "application/octet-stream",
    }
}

fn serve_file(root: &std::path::Path, rel: &str) -> Response {
    use std::path::Component;
    let p = std::path::Path::new(rel);
    for c in p.components() {
        match c {
            Component::ParentDir | Component::RootDir | Component::Prefix(_) => {
                return not_found_plain()
            }
            _ => {}
        }
    }
    let full = root.join(p);
    match std::fs::symlink_metadata(&full) {
        Ok(m) if m.is_file() => {}
        _ => return not_found_plain(),
    }
    match std::fs::read(&full) {
        Ok(data) => Response::new(200, vec![("content-type", mime_for(rel))], data),
        Err(_) => not_found_plain(),
    }
}

const HEAD: &str = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>hashcards</title><link rel=\"stylesheet\" href=\"/katex/katex.css\"><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\"><script defer src=\"/katex/katex.js\"></script><script defer src=\"/katex/mhchem.js\"></script><script defer src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"></script><link rel=\"stylesheet\" href=\"/style.css\"><style>.card-content { opacity: 0; }</style><noscript><style>.card-content { opacity: 1; }</style></noscript></head><body>";
const TAIL: &str = "<script src=\"/script.js\"></script></body></html>";

fn page(body: &str) -> Response {
    let mut html = String::from(HEAD);
    html.push_str(body);
    html.push_str(TAIL);
    Response::new(200, vec![("content-type", "text/html; charset=utf-8")], html.into_bytes())
}

fn fmt_display_time(t: &NaiveDateTime) -> String {
    t.format("%Y-%m-%d %H:%M:%S").to_string()
}

impl State {
    fn completed(&self) -> usize {
        self.total - self.queue.len()
    }

    fn is_finished(&self) -> bool {
        self.finished || self.queue.is_empty()
    }

    fn render_finished(&self) -> String {
        let reviewed = self.completed();
        let end = self.finished_at.unwrap_or_else(timeutil::now);
        let secs = (end - self.started_at).num_seconds();
        let pace = if reviewed == 0 { 0.0 } else { secs as f64 / reviewed as f64 };
        format!(
            "<div class=\"finished\"><h1>Session Completed \u{1F389}</h1><div class=\"summary\">Reviewed {} cards in {} seconds.</div><h2>Session Stats</h2><div class=\"stats\"><table><tbody><tr><td class=\"key\">Total Cards</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Cards Reviewed</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Started</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Finished</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Duration (seconds)</td><td class=\"val\">{}</td></tr><tr><td class=\"key\">Pace (s/card)</td><td class=\"val\">{:.2}</td></tr></tbody></table></div><div class=\"shutdown-container\"><form action=\"/\" method=\"post\"><input class=\"shutdown-button\" id=\"shutdown\" type=\"submit\" name=\"action\" value=\"Shutdown\" title=\"Shut down the server\"></form></div></div>",
            reviewed,
            secs,
            self.total,
            reviewed,
            fmt_display_time(&self.started_at),
            fmt_display_time(&end),
            secs,
            pace
        )
    }

    fn render_card(&self) -> Option<String> {
        let idx = self.queue[0];
        let card = &self.cards[idx];
        let ctx = markdown::RenderContext { port: self.port, rel_dir: card.rel_dir.clone() };
        let content = match &card.content {
            CardContent::Basic { question, answer } => {
                let q = markdown::render(question, &ctx);
                let a = if self.revealed { markdown::render(answer, &ctx) } else { String::new() };
                format!(
                    "<div class=\"question rich-text\">{}</div><div class=\"answer rich-text\">{}</div>",
                    q, a
                )
            }
            CardContent::Cloze { text, start, end } => {
                let start = *start;
                let end = *end;
                if start > text.len() || end >= text.len() || start > end + 1 {
                    return None;
                }
                if !text.is_char_boundary(start) || !text.is_char_boundary(end + 1) {
                    return None;
                }
                let src = if self.revealed {
                    format!(
                        "{}<span class='cloze-reveal'>{}</span>{}",
                        &text[..start],
                        &text[start..end + 1],
                        &text[end + 1..]
                    )
                } else {
                    format!(
                        "{}<span class='cloze'>.............</span>{}",
                        &text[..start],
                        &text[end + 1..]
                    )
                };
                format!("<div class=\"prompt rich-text\">{}</div>", markdown::render(&src, &ctx))
            }
        };
        let total = self.total;
        let pct = if total == 0 { 0 } else { ((self.completed() as f64 / total as f64) * 100.0) as usize };
        let undo = if self.undo.is_empty() {
            "<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" disabled>".to_string()
        } else {
            "<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" title=\"Undo last action. Shortcut: u.\">".to_string()
        };
        let middle = if !self.revealed {
            "<input id=\"reveal\" type=\"submit\" name=\"action\" value=\"Reveal\" title=\"Show the answer. Shortcut: space.\">".to_string()
        } else {
            match self.controls {
                AnswerControls::Full => "<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten. Shortcut: 1.\"><input id=\"hard\" type=\"submit\" name=\"action\" value=\"Hard\" title=\"Mark card as difficult. Shortcut: 2.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered well. Shortcut: 3.\"><input id=\"easy\" type=\"submit\" name=\"action\" value=\"Easy\" title=\"Mark card as very easy. Shortcut: 4.\"></div>".to_string(),
                AnswerControls::Binary => "<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered.\"></div>".to_string(),
            }
        };
        Some(format!(
            "<div class=\"root\"><div class=\"header\"><div class=\"progress-bar\"><div class=\"progress-fill\" style=\"width: {}%;\"></div></div></div><div class=\"card-container\"><div class=\"card\"><div class=\"card-header\"><h1>{}</h1></div><div class=\"card-content\">{}</div></div></div><div class=\"controls\"><form action=\"/\" method=\"post\">{}<div class=\"spacer\"></div>{}<div class=\"spacer\"></div><input id=\"end\" type=\"submit\" name=\"action\" value=\"End\" title=\"End the session (changes are saved)\"></form></div></div>",
            pct,
            escape_html(&card.deck_name),
            content,
            undo,
            middle
        ))
    }

    fn save(&self) -> Result<()> {
        let ended = timeutil::fmt_timestamp(&timeutil::now());
        let started = timeutil::fmt_timestamp(&self.started_at);
        let reviews: Vec<NewReview> = self.reviews.iter().map(|r| r.review.clone()).collect();
        let mut counts: HashMap<usize, i64> = HashMap::new();
        let mut order: Vec<usize> = Vec::new();
        for r in &self.reviews {
            let e = counts.entry(r.card).or_insert(0);
            if *e == 0 {
                order.push(r.card);
            }
            *e += 1;
        }
        let mut updates = Vec::new();
        for idx in order {
            if let Some(Some(p)) = self.perf.get(&idx) {
                updates.push((
                    self.cards[idx].hash.clone(),
                    Performance {
                        last_reviewed_at: p.last_reviewed_at.clone(),
                        stability: p.stability,
                        difficulty: p.difficulty,
                        interval_raw: p.interval_raw,
                        interval_days: p.interval_days,
                        due_date: p.due_date.clone(),
                        review_count: self.initial_review_count[idx] + counts[&idx],
                    },
                ));
            }
        }
        self.db.save_session(&started, &ended, &reviews, &updates)
    }

    fn grade(&mut self, g: Grade) -> Result<()> {
        if self.queue.is_empty() || !self.revealed {
            return Ok(());
        }
        let snapshot = Snapshot {
            queue: self.queue.clone(),
            reviews: self.reviews.clone(),
            perf: self.perf.clone(),
        };
        let idx = self.queue[0];
        let now = timeutil::now();
        let today = now.date();
        let prev = self.perf.get(&idx).cloned().flatten();
        let (prev_sd, elapsed) = match &prev {
            Some(p) => {
                let last = timeutil::parse_timestamp(&p.last_reviewed_at)
                    .map(|t| t.date())
                    .unwrap_or(today);
                (Some((p.stability, p.difficulty)), (today - last).num_days() as f64)
            }
            None => (None, 0.0),
        };
        let (s, d) = fsrs::review(prev_sd, elapsed, g);
        let raw = fsrs::interval(s);
        let days = fsrs::interval_days(raw);
        let due = (today + chrono::Duration::days(days)).format("%Y-%m-%d").to_string();
        let reviewed_at = timeutil::fmt_timestamp(&now);
        let perf = CardPerf {
            last_reviewed_at: reviewed_at.clone(),
            stability: s,
            difficulty: d,
            interval_raw: raw,
            interval_days: days,
            due_date: due.clone(),
        };
        self.reviews.push(SessionReview {
            card: idx,
            review: NewReview {
                hash: self.cards[idx].hash.clone(),
                reviewed_at,
                grade: g.db_name(),
                stability: s,
                difficulty: d,
                interval_raw: raw,
                interval_days: days,
                due_date: due,
            },
        });
        self.perf.insert(idx, Some(perf));
        self.undo.push(snapshot);
        self.queue.remove(0);
        if g == Grade::Forgot || g == Grade::Hard {
            self.queue.push(idx);
        }
        self.revealed = false;
        if self.queue.is_empty() {
            self.finished_at = Some(now);
            self.save()?;
        }
        Ok(())
    }
}

fn get_root(state: &Arc<Mutex<State>>) -> Response {
    let mut s = match state.lock() {
        Ok(s) => s,
        Err(_) => return Response::abort(),
    };
    if s.poisoned {
        return Response::abort();
    }
    if s.is_finished() {
        return page(&s.render_finished());
    }
    match s.render_card() {
        Some(body) => page(&body),
        None => {
            s.poisoned = true;
            Response::abort()
        }
    }
}

#[derive(Clone, Copy)]
enum Action {
    Reveal,
    Undo,
    End,
    Forgot,
    Hard,
    Good,
    Easy,
    Shutdown,
}

fn form_decode(s: &str) -> String {
    percent_decode(&s.replace('+', " "))
}

fn text_plain(status: u16, msg: &str) -> Response {
    Response::new(status, vec![("content-type", "text/plain; charset=utf-8")], msg.as_bytes().to_vec())
}

fn parse_form(req: &Request) -> std::result::Result<Action, Response> {
    let ct = req.header("Content-Type").unwrap_or("");
    let essence = ct.split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    if essence != "application/x-www-form-urlencoded" {
        return Err(text_plain(
            415,
            "Form requests must have `Content-Type: application/x-www-form-urlencoded`",
        ));
    }
    let body = String::from_utf8_lossy(&req.body).to_string();
    let mut action: Option<String> = None;
    for pair in body.split('&') {
        if pair.is_empty() {
            continue;
        }
        let (k, v) = match pair.split_once('=') {
            Some((k, v)) => (k, v),
            None => (pair, ""),
        };
        let k = form_decode(k);
        if k == "action" {
            if action.is_some() {
                return Err(text_plain(
                    422,
                    "Failed to deserialize form body: duplicate field `action`",
                ));
            }
            action = Some(form_decode(v));
        }
    }
    let a = match action {
        None => {
            return Err(text_plain(422, "Failed to deserialize form body: missing field `action`"))
        }
        Some(a) => a,
    };
    Ok(match a.as_str() {
        "Reveal" => Action::Reveal,
        "Undo" => Action::Undo,
        "End" => Action::End,
        "Forgot" => Action::Forgot,
        "Hard" => Action::Hard,
        "Good" => Action::Good,
        "Easy" => Action::Easy,
        "Shutdown" => Action::Shutdown,
        other => {
            return Err(text_plain(
                422,
                &format!(
                    "Failed to deserialize form body: action: unknown variant `{}`, expected one of `Reveal`, `Undo`, `End`, `Forgot`, `Hard`, `Good`, `Easy`, `Shutdown`",
                    other
                ),
            ))
        }
    })
}

fn redirect() -> Response {
    Response::empty(303, vec![("location", "/")])
}

fn post_root(state: &Arc<Mutex<State>>, req: &Request) -> (Response, After) {
    let action = match parse_form(req) {
        Ok(a) => a,
        Err(r) => return (r, After::Continue),
    };
    let mut s = match state.lock() {
        Ok(s) => s,
        Err(_) => return (Response::abort(), After::Continue),
    };
    if s.poisoned {
        return (Response::abort(), After::Continue);
    }
    let result: Result<After> = (|| {
        match action {
            Action::Reveal => {
                if !s.queue.is_empty() {
                    s.revealed = true;
                }
            }
            Action::Undo => {
                if let Some(snap) = s.undo.pop() {
                    s.queue = snap.queue;
                    s.reviews = snap.reviews;
                    s.perf = snap.perf;
                    s.revealed = false;
                    s.finished = false;
                }
            }
            Action::End => {
                s.save()?;
                s.finished = true;
                s.finished_at = Some(timeutil::now());
            }
            Action::Forgot => s.grade(Grade::Forgot)?,
            Action::Hard => s.grade(Grade::Hard)?,
            Action::Good => s.grade(Grade::Good)?,
            Action::Easy => s.grade(Grade::Easy)?,
            Action::Shutdown => {
                if s.is_finished() {
                    return Ok(After::Exit(0));
                }
            }
        }
        Ok(After::Continue)
    })();
    match result {
        Ok(after) => (redirect(), after),
        Err(e) => (text_plain(500, &e.to_string()), After::Continue),
    }
}
EOF
echo done"}

