//! The `drill` command: a web interface for reviewing cards.

use crate::collection::{self, percent_decode};
use crate::db::{Database, NewReview, Performance};
use crate::error::{Error, Result};
use crate::fsrs::{self, Grade};
use crate::http::{self, After, Request, Response};
use crate::markdown;
use crate::parser::{Card, CardContent};
use crate::timeutil;
use chrono::NaiveDateTime;
use rand::seq::SliceRandom;
use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum AnswerControls {
    Full,
    Binary,
}

pub struct DrillOptions {
    pub card_limit: Option<usize>,
    pub new_card_limit: Option<usize>,
    pub host: String,
    pub port: u16,
    pub from_deck: Option<String>,
    pub open_browser: Option<bool>,
    pub answer_controls: AnswerControls,
    pub bury_siblings: Option<bool>,
}

#[derive(Clone)]
struct CardPerf {
    last_reviewed_at: String,
    stability: f64,
    difficulty: f64,
    interval_raw: f64,
    interval_days: i64,
    due_date: String,
}

#[derive(Clone)]
struct SessionReview {
    card: usize,
    review: NewReview,
}

#[derive(Clone)]
struct Snapshot {
    queue: Vec<usize>,
    reviews: Vec<SessionReview>,
    perf: HashMap<usize, Option<CardPerf>>,
}

struct State {
    cards: Vec<Card>,
    initial_review_count: Vec<i64>,
    queue: Vec<usize>,
    total: usize,
    revealed: bool,
    reviews: Vec<SessionReview>,
    perf: HashMap<usize, Option<CardPerf>>,
    undo: Vec<Snapshot>,
    finished: bool,
    finished_at: Option<NaiveDateTime>,
    started_at: NaiveDateTime,
    db: Database,
    port: u16,
    controls: AnswerControls,
    macros_js: String,
    root: PathBuf,
    poisoned: bool,
}

const STYLE_CSS: &[u8] = include_bytes!("../assets/style.css");
const SCRIPT_JS: &str = include_str!("../assets/script.js");
const KATEX_CSS: &[u8] = include_bytes!("../assets/katex/katex.css");
const KATEX_JS: &[u8] = include_bytes!("../assets/katex/katex.js");
const MHCHEM_JS: &[u8] = include_bytes!("../assets/katex/mhchem.js");

macro_rules! fonts {
    ($($name:literal),*) => {
        &[$(($name, include_bytes!(concat!("../assets/katex/fonts/", $name)) as &[u8])),*]
    };
}

const FONTS: &[(&str, &[u8])] = fonts!(
    "KaTeX_AMS-Regular.woff2",
    "KaTeX_Caligraphic-Bold.woff2",
    "KaTeX_Caligraphic-Regular.woff2",
    "KaTeX_Fraktur-Bold.woff2",
    "KaTeX_Fraktur-Regular.woff2",
    "KaTeX_Main-Bold.woff2",
    "KaTeX_Main-BoldItalic.woff2",
    "KaTeX_Main-Italic.woff2",
    "KaTeX_Main-Regular.woff2",
    "KaTeX_Math-BoldItalic.woff2",
    "KaTeX_Math-Italic.woff2",
    "KaTeX_SansSerif-Bold.woff2",
    "KaTeX_SansSerif-Italic.woff2",
    "KaTeX_SansSerif-Regular.woff2",
    "KaTeX_Script-Regular.woff2",
    "KaTeX_Size1-Regular.woff2",
    "KaTeX_Size2-Regular.woff2",
    "KaTeX_Size3-Regular.woff2",
    "KaTeX_Size4-Regular.woff2",
    "KaTeX_Typewriter-Regular.woff2"
);

const CACHE: &str = "public, max-age=604800, immutable";

pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

fn is_due(perf: &Option<Performance>, today: &str) -> bool {
    match perf {
        None => true,
        Some(p) => p.due_date.as_str() <= today,
    }
}

pub fn run(dir: Option<&str>, opts: DrillOptions) -> Result<()> {
    let coll = collection::load(dir)?;
    let started_at = timeutil::now();
    let now_str = timeutil::fmt_timestamp(&started_at);
    let db_cards = coll.db.all_cards()?;
    let new_hashes: Vec<String> = coll
        .cards
        .iter()
        .filter(|c| !db_cards.contains_key(&c.hash))
        .map(|c| c.hash.clone())
        .collect();
    coll.db.insert_new_cards(&new_hashes, &now_str)?;
    let today = started_at.date().format("%Y-%m-%d").to_string();

    let mut selected: Vec<Card> = Vec::new();
    let mut perfs: Vec<Option<Performance>> = Vec::new();
    let mut counts: Vec<i64> = Vec::new();
    for card in &coll.cards {
        let dbc = db_cards.get(&card.hash);
        let perf = dbc.and_then(|d| d.performance.clone());
        if !is_due(&perf, &today) {
            continue;
        }
        if let Some(deck) = &opts.from_deck {
            if &card.deck_name != deck {
                continue;
            }
        }
        selected.push(card.clone());
        perfs.push(perf);
        counts.push(dbc.map(|d| d.review_count).unwrap_or(0));
    }
    let mut items: Vec<(Card, Option<Performance>, i64)> = selected
        .into_iter()
        .zip(perfs)
        .zip(counts)
        .map(|((c, p), n)| (c, p, n))
        .collect();
    if let Some(limit) = opts.card_limit {
        items.truncate(limit);
    }
    if let Some(limit) = opts.new_card_limit {
        let mut n_new = 0;
        items.retain(|(_, p, _)| {
            if p.is_none() {
                n_new += 1;
                n_new <= limit
            } else {
                true
            }
        });
    }
    if opts.bury_siblings.unwrap_or(true) {
        let mut seen = HashSet::new();
        items.retain(|(c, _, _)| match &c.family_hash {
            Some(f) => seen.insert(f.clone()),
            None => true,
        });
    }
    if items.is_empty() {
        println!("No cards due today.");
        return Ok(());
    }
    let mut cards = Vec::new();
    let mut perf = HashMap::new();
    let mut initial_review_count = Vec::new();
    for (i, (c, p, n)) in items.into_iter().enumerate() {
        cards.push(c);
        perf.insert(
            i,
            p.map(|p| CardPerf {
                last_reviewed_at: p.last_reviewed_at,
                stability: p.stability,
                difficulty: p.difficulty,
                interval_raw: p.interval_raw,
                interval_days: p.interval_days,
                due_date: p.due_date,
            }),
        );
        initial_review_count.push(n);
    }
    let mut queue: Vec<usize> = (0..cards.len()).collect();
    queue.shuffle(&mut rand::thread_rng());

    let listener = http::bind(&opts.host, opts.port)?;

    let mut macros_js = String::from("let MACROS = {};\n");
    for (name, def) in &coll.macros {
        macros_js.push_str(&format!(
            "MACROS['{}'] = '{}';\n",
            name.replace('\\', "\\\\"),
            def.replace('\\', "\\\\")
        ));
    }
    macros_js.push('\n');
    macros_js.push_str(SCRIPT_JS);

    let total = cards.len();
    let state = State {
        cards,
        initial_review_count,
        queue,
        total,
        revealed: false,
        reviews: Vec::new(),
        perf,
        undo: Vec::new(),
        finished: false,
        finished_at: None,
        started_at,
        db: coll.db,
        port: opts.port,
        controls: opts.answer_controls,
        macros_js,
        root: coll.root.clone(),
        poisoned: false,
    };
    let state = Arc::new(Mutex::new(state));

    install_sigint_handler(state.clone());

    if opts.open_browser.unwrap_or(true) {
        open_browser(&format!("http://{}:{}/", opts.host, opts.port));
    }

    let st = state.clone();
    http::serve(listener, move |req| handle(&st, req));
    let _ = Error::Msg(String::new());
    Ok(())
}

fn open_browser(url: &str) {
    let _ = std::process::Command::new("xdg-open")
        .arg(url)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn();
}

fn install_sigint_handler(state: Arc<Mutex<State>>) {
    unsafe {
        let mut set: libc::sigset_t = std::mem::zeroed();
        libc::sigemptyset(&mut set);
        libc::sigaddset(&mut set, libc::SIGINT);
        libc::pthread_sigmask(libc::SIG_BLOCK, &set, std::ptr::null_mut());
    }
    std::thread::spawn(move || loop {
        let mut sig: libc::c_int = 0;
        unsafe {
            let mut set: libc::sigset_t = std::mem::zeroed();
            libc::sigemptyset(&mut set);
            libc::sigaddset(&mut set, libc::SIGINT);
            libc::sigwait(&set, &mut sig);
        }
        if sig == libc::SIGINT {
            let done = match state.lock() {
                Ok(s) => s.finished || s.queue.is_empty(),
                Err(_) => false,
            };
            if done {
                std::process::exit(0);
            } else {
                eprintln!("hashcards: error: Session interrupted before completion");
                std::process::exit(1);
            }
        }
    });
}

fn not_found_html() -> Response {
    Response::new(404, vec![("content-type", "text/html; charset=utf-8")], b"Not Found".to_vec())
}

fn not_found_plain() -> Response {
    Response::new(404, vec![("content-type", "text/plain")], b"Not Found".to_vec())
}

fn method_not_allowed(allow: &str) -> Response {
    Response::empty(405, vec![("allow", allow)])
}

fn handle(state: &Arc<Mutex<State>>, req: &Request) -> (Response, After) {
    let path = req.path.as_str();
    let is_get = req.method == "GET" || req.method == "HEAD";
    let static_asset = |ct: &str, body: &[u8], cache: bool| -> (Response, After) {
        if !is_get {
            return (method_not_allowed("GET,HEAD"), After::Continue);
        }
        let mut headers = vec![("content-type", ct)];
        if cache {
            headers.push(("cache-control", CACHE));
        }
        (Response::new(200, headers, body.to_vec()), After::Continue)
    };
    match path {
        "/" => {
            if is_get {
                (get_root(state), After::Continue)
            } else if req.method == "POST" {
                post_root(state, req)
            } else {
                (method_not_allowed("GET,HEAD,POST"), After::Continue)
            }
        }
        "/style.css" => static_asset("text/css", STYLE_CSS, true),
        "/katex/katex.css" => static_asset("text/css", KATEX_CSS, true),
        "/katex/katex.js" => static_asset("text/javascript", KATEX_JS, true),
        "/katex/mhchem.js" => static_asset("text/javascript", MHCHEM_JS, true),
        "/script.js" => {
            let js = match state.lock() {
                Ok(s) => s.macros_js.clone(),
                Err(_) => return (Response::abort(), After::Continue),
            };
            static_asset("text/javascript", js.as_bytes(), false)
        }
        _ => {
            if let Some(name) = path.strip_prefix("/katex/fonts/") {
                if name.is_empty() {
                    return (not_found_html(), After::Continue);
                }
                if !is_get {
                    return (method_not_allowed("GET,HEAD"), After::Continue);
                }
                let name = percent_decode(name);
                for (n, data) in FONTS {
                    if *n == name {
                        return (
                            Response::new(
                                200,
                                vec![("content-type", "font/woff2"), ("cache-control", CACHE)],
                                data.to_vec(),
                            ),
                            After::Continue,
                        );
                    }
                }
                return (
                    Response::new(
                        404,
                        vec![("content-type", "text/plain"), ("cache-control", "no-cache")],
                        b"Not Found".to_vec(),
                    ),
                    After::Continue,
                );
            }
            if let Some(rest) = path.strip_prefix("/file/") {
                if rest.is_empty() {
                    return (not_found_html(), After::Continue);
                }
                if !is_get {
                    return (method_not_allowed("GET,HEAD"), After::Continue);
                }
                let root = match state.lock() {
                    Ok(s) => s.root.clone(),
                    Err(_) => return (Response::abort(), After::Continue),
                };
                return (serve_file(&root, &percent_decode(rest)), After::Continue);
            }
            (not_found_html(), After::Continue)
        }
    }
}

fn mime_for(path: &str) -> &'static str {
    let ext = std::path::Path::new(path)
        .extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    match ext.as_str() {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "ogg" => "audio/ogg",
        "mp4" => "video/mp4",
        "webm" => "video/webm",
        _ => "application/octet-stream",
    }
}

fn serve_file(root: &std::path::Path, rel: &str) -> Response {
    use std::path::Component;
    let p = std::path::Path::new(rel);
    for c in p.components() {
        match c {
            Component::ParentDir | Component::RootDir | Component::Prefix(_) => {
                return not_found_plain()
            }
            _ => {}
        }
    }
    let full = root.join(p);
    match std::fs::symlink_metadata(&full) {
        Ok(m) if m.is_file() => {}
        _ => return not_found_plain(),
    }
    match std::fs::read(&full) {
        Ok(data) => Response::new(200, vec![("content-type", mime_for(rel))], data),
        Err(_) => not_found_plain(),
    }
}

const HEAD: &str = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>hashcards</title><link rel=\"stylesheet\" href=\"/katex/katex.css\"><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\"><script defer src=\"/katex/katex.js\"></script><script defer src=\"/katex/mhchem.js\"></script><script defer src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"></script><link rel=\"stylesheet\" href=\"/style.css\"><style>.card-content { opacity: 0; }</style><noscript><style>.card-content { opacity: 1; }</style></noscript></head><body>";
