import sys, random, re, socket, subprocess, time, os, tempfile, shutil
sys.path.insert(0,'/tmp')
from dcmp import req, norm, dbdump, ORIG, MINE
def drive(exe, files, policy, args=(), port=8260, setup=None, maxsteps=60):
    d=tempfile.mkdtemp(prefix='/tmp/mc.')
    for k,v in files.items():
        p=os.path.join(d,k); os.makedirs(os.path.dirname(p),exist_ok=True)
        open(p,'w').write(v)
    if setup: setup(d)
    p=subprocess.Popen([exe,'drill','--open-browser','false','--port',str(port)]+list(args)+[d],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    for i in range(100):
        try: socket.create_connection(('127.0.0.1',port),timeout=1).close(); break
        except Exception:
            if p.poll() is not None: break
            time.sleep(0.05)
    visits={}
    pages=[]
    for step in range(maxsteps):
        if p.poll() is not None: break
        r=req(port,'GET','/')
        m=re.search(rb'<p>(q\d+)</p>',r)
        if not m:
            pages.append(norm(r)); break
        q=m.group(1).decode()
        n=visits.get(q,0); visits[q]=n+1
        prog=re.search(rb'width: (\d+)%',r).group(1)
        pages.append((q,n,prog))
        req(port,'POST','/','action=Reveal',{'Content-Type':'application/x-www-form-urlencoded'})
        g=policy(q,n)
        req(port,'POST','/',f'action={g}',{'Content-Type':'application/x-www-form-urlencoded'})
    time.sleep(0.1)
    if p.poll() is None: p.kill()
    out,err=p.communicate()
    db=dbdump(d)
    shutil.rmtree(d)
    return sorted(pages,key=str),(p.returncode,out,err),db
def canon_db(db):
    if db is None: return None
    schema=[x for x in db if len(x)==3 and x[0] in ('table','index')]
    rows=sorted([x for x in db if x not in schema],key=str)
    return schema,rows
def compare(files, policy, args=(), setup=None, label=''):
    a=drive(ORIG,files,policy,args,8260,setup)
    b=drive(MINE,files,policy,args,8261,setup)
    ok=True
    if a[0]!=b[0]: ok=False; print('PAGES differ',label); print(' o',a[0][:20]); print(' m',b[0][:20])
    if a[1][1:]!=b[1][1:]: ok=False; print('PROC differ',a[1],b[1])
    ca,cb=canon_db(a[2]),canon_db(b[2])
    if ca!=cb:
        ok=False; print('DB differ',label)
        for x,y in zip(ca[1],cb[1]):
            if x!=y: print(' o',x); print(' m',y)
    return ok
if __name__=='__main__':
