use crate::entities::{ENTITIES, PUNCT, SPACE_SEP, SYMBOL};

pub fn is_ascii_punct(c: char) -> bool {
    c.is_ascii_punctuation()
}

fn in_ranges(table: &[(u32, u32)], c: char) -> bool {
    let cp = c as u32;
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
