        .binary_search_by(|(k, _)| (*k).cmp(name))
        .ok()
        .map(|i| ENTITIES[i].1)
}

/// Normalize a link label for matching.
pub fn normalize_label(s: &str) -> String {
    let mut out = String::new();
    let mut in_ws = false;
    for c in s.trim_matches(|c: char| is_unicode_whitespace(c)).chars() {
        if is_unicode_whitespace(c) {
            if !in_ws {
                out.push(' ');
            }
            in_ws = true;
        } else {
            in_ws = false;
            out.push(c);
        }
    }
    out.to_uppercase().to_lowercase()
}

/// Process backslash escapes and entity references in a string (used for
/// link destinations, titles and info strings).
pub fn unescape_string(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() && is_ascii_punct(chars[i + 1]) {
            out.push(chars[i + 1]);
            i += 2;
            continue;
        }
        if c == '&' {
            if let Some((rep, len)) = parse_entity(&chars[i..]) {
                out.push_str(&rep);
                i += len;
                continue;
            }
        }
        out.push(c);
        i += 1;
    }
    out
}

/// Try to parse an entity reference at the start of `chars` (which begins
/// with '&'). Returns the replacement text and number of chars consumed.
pub fn parse_entity(chars: &[char]) -> Option<(String, usize)> {
    if chars.len() < 3 || chars[0] != '&' {
        return None;
    }
    if chars[1] == '#' {
        let (hex, start) = if chars.len() > 2 && (chars[2] == 'x' || chars[2] == 'X') {
            (true, 3)
        } else {
            (false, 2)
        };
        let mut j = start;
        let maxlen = if hex { 6 } else { 7 };
        while j < chars.len() && j - start < maxlen + 1 {
            let c = chars[j];
            let ok = if hex { c.is_ascii_hexdigit() } else { c.is_ascii_digit() };
            if !ok {
                break;
            }
            j += 1;
        }
        let ndigits = j - start;
        if ndigits == 0 || ndigits > maxlen || j >= chars.len() || chars[j] != ';' {
            return None;
        }
        let digits: String = chars[start..j].iter().collect();
        let v = u32::from_str_radix(&digits, if hex { 16 } else { 10 }).ok()?;
        let c = if v == 0 { '\u{FFFD}' } else { char::from_u32(v).unwrap_or('\u{FFFD}') };
        return Some((c.to_string(), j + 1));
    }
    let mut j = 1;
    while j < chars.len() && chars[j].is_ascii_alphanumeric() && j < 40 {
        j += 1;
    }
    if j == 1 || j >= chars.len() || chars[j] != ';' {
        return None;
    }
    let name: String = chars[1..j].iter().collect();
    lookup_entity(&name).map(|v| (v.to_string(), j + 1))
}

pub fn escape_html(out: &mut String, s: &str) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
}

pub fn escape_html_body(out: &mut String, s: &str) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
}

