//! Block-level parsing, closely following the CommonMark reference algorithm.

use super::util::*;
use std::collections::HashMap;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ListType {
    Bullet,
    Ordered,
}

#[derive(Clone, Copy, Debug)]
pub struct ListData {
    pub list_type: ListType,
    pub marker_offset: usize,
    pub padding: usize,
    pub start: u64,
    pub delimiter: u8,
    pub bullet_char: u8,
    pub tight: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Align {
    None,
    Left,
    Center,
    Right,
}

#[derive(Clone, Debug)]
pub enum Kind {
    Document,
    BlockQuote,
    List(ListData),
    Item(ListData),
    Paragraph,
    Heading { level: u8, setext: bool },
    ThematicBreak,
    CodeBlock { fenced: bool, fence_char: u8, fence_length: usize, fence_offset: usize, info: String },
    HtmlBlock { html_type: u8 },
    Table { aligns: Vec<Align>, header: Vec<String>, rows: Vec<Vec<String>> },
}

#[derive(Clone, Debug)]
pub struct Node {
    pub kind: Kind,
    pub parent: Option<usize>,
    pub children: Vec<usize>,
    pub open: bool,
    pub last_line_blank: bool,
    pub start_line: usize,
    pub content: String,
}

pub struct Document {
    pub nodes: Vec<Node>,
    pub refmap: HashMap<String, (String, String)>,
}

impl Document {
    pub fn root(&self) -> usize {
        0
    }
}

const TAB_STOP: usize = 4;
const CODE_INDENT: usize = 4;

struct Parser {
    nodes: Vec<Node>,
    refmap: HashMap<String, (String, String)>,
    current: usize,
    line_number: usize,
    offset: usize,
    column: usize,
    first_nonspace: usize,
    first_nonspace_column: usize,
    indent: usize,
    blank: bool,
    partially_consumed_tab: bool,
    thematic_break_kill_pos: usize,
}

fn peek(line: &[u8], pos: usize) -> u8 {
    if pos < line.len() {
        line[pos]
    } else {
        0
    }
}

fn is_space_or_tab(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

fn is_line_end(c: u8) -> bool {
    c == 0 || c == b'\n' || c == b'\r'
}

impl Parser {
    fn new() -> Parser {
        let root = Node {
            kind: Kind::Document,
            parent: None,
            children: Vec::new(),
            open: true,
            last_line_blank: false,
            start_line: 1,
            content: String::new(),
        };
        Parser {
            nodes: vec![root],
            refmap: HashMap::new(),
            current: 0,
            line_number: 0,
            offset: 0,
            column: 0,
            first_nonspace: 0,
            first_nonspace_column: 0,
            indent: 0,
            blank: false,
            partially_consumed_tab: false,
            thematic_break_kill_pos: 0,
        }
    }

    fn last_child_is_open(&self, n: usize) -> Option<usize> {
        match self.nodes[n].children.last() {
            Some(&c) if self.nodes[c].open => Some(c),
            _ => None,
        }
    }

    fn find_first_nonspace(&mut self, line: &[u8]) {
        let mut chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
        if self.first_nonspace <= self.offset {
            self.first_nonspace = self.offset;
            self.first_nonspace_column = self.column;
            loop {
                let c = peek(line, self.first_nonspace);
                if c == b' ' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += 1;
                    chars_to_tab -= 1;
                    if chars_to_tab == 0 {
                        chars_to_tab = TAB_STOP;
                    }
                } else if c == b'\t' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += chars_to_tab;
                    chars_to_tab = TAB_STOP;
                } else {
                    break;
                }
            }
        }
        self.indent = self.first_nonspace_column - self.column;
        self.blank = is_line_end(peek(line, self.first_nonspace));
    }

    fn advance_offset(&mut self, line: &[u8], mut count: usize, columns: bool) {
        while count > 0 {
            let c = peek(line, self.offset);
            if c == 0 {
                break;
            }
            if c == b'\t' {
                let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
                if columns {
                    self.partially_consumed_tab = chars_to_tab > count;
                    let adv = count.min(chars_to_tab);
                    self.column += adv;
                    if !self.partially_consumed_tab {
                        self.offset += 1;
                    }
                    count -= adv;
                } else {
                    self.partially_consumed_tab = false;
                    self.column += chars_to_tab;
                    self.offset += 1;
                    count -= 1;
                }
            } else {
                self.partially_consumed_tab = false;
                self.offset += 1;
                self.column += 1;
                count -= 1;
            }
        }
    }

    fn add_line(&mut self, node: usize, line: &[u8]) {
        if self.partially_consumed_tab {
            self.offset += 1;
            let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
            for _ in 0..chars_to_tab {
                self.nodes[node].content.push(' ');
            }
        }
        if self.offset < line.len() {
            let s = String::from_utf8_lossy(&line[self.offset..]).to_string();
            self.nodes[node].content.push_str(&s);
        }
        self.nodes[node].content.push('\n');
    }

    fn can_contain(&self, parent: usize, child: &Kind) -> bool {
        match &self.nodes[parent].kind {
            Kind::Document | Kind::BlockQuote | Kind::Item(_) => !matches!(child, Kind::Item(_)),
            Kind::List(_) => matches!(child, Kind::Item(_)),
            _ => false,
        }
    }

    fn add_child(&mut self, mut parent: usize, kind: Kind) -> usize {
        while !self.can_contain(parent, &kind) {
            parent = self.finalize(parent);
        }
        let node = Node {
            kind,
            parent: Some(parent),
            children: Vec::new(),
            open: true,
            last_line_blank: false,
            start_line: self.line_number,
            content: String::new(),
        };
        self.nodes.push(node);
        let id = self.nodes.len() - 1;
        self.nodes[parent].children.push(id);
        id
    }

    fn remove_node(&mut self, n: usize) {
        if let Some(p) = self.nodes[n].parent {
            self.nodes[p].children.retain(|&c| c != n);
        }
    }

    fn ends_with_blank_line(&self, n: usize) -> bool {
        let mut cur = Some(n);
        while let Some(c) = cur {
            if self.nodes[c].last_line_blank {
                return true;
            }
            match self.nodes[c].kind {
                Kind::List(_) | Kind::Item(_) => cur = self.nodes[c].children.last().copied(),
                _ => cur = None,
            }
        }
        false
    }

    fn finalize(&mut self, b: usize) -> usize {
        let parent = self.nodes[b].parent.unwrap_or(0);
        self.nodes[b].open = false;
        match self.nodes[b].kind.clone() {
            Kind::Paragraph => {
                let has_content = self.resolve_reference_link_definitions(b);
                if !has_content {
                    self.remove_node(b);
                } else {
                    self.detect_table(b);
                }
            }
            Kind::CodeBlock { fenced, fence_char, fence_length, fence_offset, .. } => {
                if !fenced {
                    // remove trailing blank lines
                    let content = std::mem::take(&mut self.nodes[b].content);
                    let mut lines: Vec<&str> = content.split('\n').collect();
                    // content ends with '\n' so last is empty
                    if lines.last() == Some(&"") {
                        lines.pop();
                    }
                    while let Some(l) = lines.last() {
                        if l.chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
                            lines.pop();
                        } else {
                            break;
                        }
                    }
                    let mut s = lines.join("\n");
                    s.push('\n');
                    self.nodes[b].content = s;
                } else {
                    let content = std::mem::take(&mut self.nodes[b].content);
                    let (first, rest) = match content.find('\n') {
                        Some(p) => (&content[..p], &content[p + 1..]),
                        None => (content.as_str(), ""),
                    };
                    let info = unescape_string(first.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\r' || c == '\n'));
                    let rest = rest.to_string();
                    self.nodes[b].kind = Kind::CodeBlock { fenced, fence_char, fence_length, fence_offset, info };
                    self.nodes[b].content = rest;
                }
            }
            Kind::List(mut data) => {
                let mut tight = true;
                let items = self.nodes[b].children.clone();
                'outer: for (ii, &item) in items.iter().enumerate() {
                    let has_next = ii + 1 < items.len();
                    if self.nodes[item].last_line_blank && has_next {
                        tight = false;
                        break;
                    }
                    let subs = self.nodes[item].children.clone();
                    for (si, &sub) in subs.iter().enumerate() {
                        let sub_next = si + 1 < subs.len();
                        if (has_next || sub_next) && self.ends_with_blank_line(sub) {
                            tight = false;
                            break 'outer;
                        }
                    }
                }
                data.tight = tight;
                self.nodes[b].kind = Kind::List(data);
            }
            _ => {}
        }
        parent
    }

    /// Parse link reference definitions at the start of the paragraph.
    /// Returns true if content remains.
    fn resolve_reference_link_definitions(&mut self, b: usize) -> bool {
        let content = std::mem::take(&mut self.nodes[b].content);
        let chars: Vec<char> = content.chars().collect();
        let mut pos = 0;
        loop {
            if pos >= chars.len() || chars[pos] != '[' {
                break;
            }
            match parse_reference(&chars, pos) {
                Some((label, dest, title, newpos)) => {
                    let norm = normalize_label(&label);
                    if !norm.is_empty() && !self.refmap.contains_key(&norm) {
                        self.refmap.insert(norm, (dest, title));
                    }
                    pos = newpos;
                }
                None => break,
            }
        }
        let rest: String = chars[pos..].iter().collect();
        let has = !rest.chars().all(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r');
        self.nodes[b].content = rest;
        has
    }

    /// Detect a table inside a finalized paragraph and split it.
    fn detect_table(&mut self, b: usize) {
        let content = self.nodes[b].content.clone();
        let lines: Vec<&str> = content.trim_end_matches('\n').split('\n').collect();
        for i in 0..lines.len().saturating_sub(1) {
            let head = lines[i];
            let delim = lines[i + 1];
            if let Some((header, aligns)) = table_head(head, delim) {
                let mut rows = Vec::new();
                for l in &lines[i + 2..] {
                    let mut cells = split_row(l);
                    cells.resize(header.len(), String::new());
                    rows.push(cells);
                }
                let parent = self.nodes[b].parent.unwrap();
                let idx = self.nodes[parent].children.iter().position(|&c| c == b).unwrap();
                let table = Node {
                    kind: Kind::Table { aligns, header, rows },
                    parent: Some(parent),
                    children: Vec::new(),
                    open: false,
                    last_line_blank: self.nodes[b].last_line_blank,
                    start_line: self.nodes[b].start_line,
                    content: String::new(),
                };
                self.nodes.push(table);
                let tid = self.nodes.len() - 1;
                if i == 0 {
                    self.nodes[parent].children[idx] = tid;
                } else {
                    let mut para = lines[..i].join("\n");
                    para.push('\n');
                    self.nodes[b].content = para;
                    self.nodes[b].last_line_blank = false;
                    self.nodes[parent].children.insert(idx + 1, tid);
                }
                return;
            }
        }
    }

    fn process_line(&mut self, line_str: &str) {
        let line = line_str.as_bytes();
        self.offset = 0;
        self.column = 0;
        self.first_nonspace = 0;
        self.first_nonspace_column = 0;
        self.thematic_break_kill_pos = 0;
        self.indent = 0;
        self.blank = false;
        self.partially_consumed_tab = false;
        self.line_number += 1;

        let (last_matched, all_matched, should_continue) = self.check_open_blocks(line);
        if !should_continue {
            return;
        }
        let mut container = last_matched;
        let current_before = self.current;
        self.open_new_blocks(&mut container, line, all_matched);
        let _ = current_before;
        self.add_text_to_container(container, last_matched, line);
    }

    fn check_open_blocks(&mut self, line: &[u8]) -> (usize, bool, bool) {
        let mut container = 0;
        let mut all_matched = false;
        let mut should_continue = true;
        let mut failed = false;
        while let Some(child) = self.last_child_is_open(container) {
            container = child;
            self.find_first_nonspace(line);
            let ok = match self.nodes[container].kind.clone() {
                Kind::BlockQuote => {
                    if self.indent <= 3 && peek(line, self.first_nonspace) == b'>' {
                        self.advance_offset(line, self.indent + 1, true);
                        if is_space_or_tab(peek(line, self.offset)) {
                            self.advance_offset(line, 1, true);
                        }
                        true
                    } else {
                        false
                    }
                }
                Kind::Item(data) => {
                    if self.indent >= data.marker_offset + data.padding {
                        self.advance_offset(line, data.marker_offset + data.padding, true);
                        true
                    } else if self.blank && !self.nodes[container].children.is_empty() {
                        let n = self.first_nonspace - self.offset;
                        self.advance_offset(line, n, false);
                        true
                    } else {
                        false
                    }
                }
                Kind::CodeBlock { fenced, fence_char, fence_length, fence_offset, .. } => {
                    if !fenced {
                        if self.indent >= CODE_INDENT {
                            self.advance_offset(line, CODE_INDENT, true);
                            true
                        } else if self.blank {
                            let n = self.first_nonspace - self.offset;
                            self.advance_offset(line, n, false);
                            true
                        } else {
                            false
                        }
                    } else {
                        let mut matched = 0;
                        if self.indent <= 3 && peek(line, self.first_nonspace) == fence_char {
                            matched = scan_close_code_fence(line, self.first_nonspace);
                        }
                        if matched >= fence_length {
                            should_continue = false;
                            self.advance_offset(line, matched, false);
                            self.current = self.finalize(container);
                            true
                        } else {
                            let mut i = fence_offset;
                            while i > 0 && is_space_or_tab(peek(line, self.offset)) {
                                self.advance_offset(line, 1, true);
                                i -= 1;
                            }
                            true
                        }
                    }
                }
                Kind::Heading { .. } => false,
                Kind::HtmlBlock { html_type } => match html_type {
                    1..=5 => true,
                    _ => !self.blank,
                },
                Kind::Paragraph => !self.blank,
                _ => true,
            };
            if !ok {
                failed = true;
                break;
            }
            if !should_continue {
                break;
            }
        }
        if !failed {
            all_matched = true;
        }
        if failed {
            container = self.nodes[container].parent.unwrap_or(0);
        }
        (container, all_matched, should_continue)
    }

    fn open_new_blocks(&mut self, container: &mut usize, line: &[u8], all_matched: bool) {
        let mut maybe_lazy = matches!(self.nodes[self.current].kind, Kind::Paragraph);
        loop {
            let cont_kind = self.nodes[*container].kind.clone();
            if matches!(cont_kind, Kind::CodeBlock { .. } | Kind::HtmlBlock { .. }) {
                break;
            }
            self.find_first_nonspace(line);
            let indented = self.indent >= CODE_INDENT;
            let is_para = matches!(cont_kind, Kind::Paragraph);
            let fns = self.first_nonspace;
            if !indented && peek(line, fns) == b'>' {
                let n = fns + 1 - self.offset;
                self.advance_offset(line, n, false);
                if is_space_or_tab(peek(line, self.offset)) {
                    self.advance_offset(line, 1, true);
                }
                *container = self.add_child(*container, Kind::BlockQuote);
            } else if let (false, Some(matched)) = (indented, scan_atx_heading_start(line, fns)) {
                let n = fns + matched - self.offset;
                self.advance_offset(line, n, false);
                let mut level = 0;
                let mut p = fns;
                while peek(line, p) == b'#' {
                    level += 1;
                    p += 1;
                }
                *container = self.add_child(*container, Kind::Heading { level, setext: false });
            } else if let (false, Some(matched)) = (indented, scan_open_code_fence(line, fns)) {
                let fence_char = peek(line, fns);
                let fence_offset = fns - self.offset;
                *container = self.add_child(
                    *container,
                    Kind::CodeBlock {
                        fenced: true,
                        fence_char,
                        fence_length: matched,
                        fence_offset,
                        info: String::new(),
                    },
                );
                let n = fns + matched - self.offset;
                self.advance_offset(line, n, false);
            } else if let (false, Some(t)) = (indented, scan_html_block_start(line, fns, !is_para)) {
                *container = self.add_child(*container, Kind::HtmlBlock { html_type: t });
            } else if let (false, true, Some(lev)) = (indented, is_para, scan_setext_heading_line(line, fns)) {
                let has_content = self.resolve_reference_link_definitions(*container);
                if has_content && !paragraph_has_table(&self.nodes[*container].content) {
                    self.nodes[*container].kind = Kind::Heading { level: lev, setext: true };
                    let n = line.len() - self.offset;
                    self.advance_offset(line, n, false);
                } else if has_content {
                    // treat as a table row: fall through to adding text
                    break;
                }
            } else if !indented
                && !(is_para && !all_matched)
                && self.thematic_break_kill_pos <= fns
                && self.scan_thematic_break(line, fns)
            {
                *container = self.add_child(*container, Kind::ThematicBreak);
                let n = line.len() - self.offset;
                self.advance_offset(line, n, false);
            } else if let (true, Some((matched, mut data))) = (
                (!indented || matches!(cont_kind, Kind::List(_))) && self.indent < 4,
                parse_list_marker(line, fns, is_para),
            ) {
                let n = fns + matched - self.offset;
                self.advance_offset(line, n, false);
                let save_ptab = self.partially_consumed_tab;
                let save_offset = self.offset;
                let save_column = self.column;
                while self.column - save_column <= 5 && is_space_or_tab(peek(line, self.offset)) {
                    self.advance_offset(line, 1, true);
                }
                let i = self.column - save_column;
                if i >= 5 || i < 1 || is_line_end(peek(line, self.offset)) {
                    data.padding = matched + 1;
                    self.offset = save_offset;
                    self.column = save_column;
                    self.partially_consumed_tab = save_ptab;
                    if i > 0 {
                        self.advance_offset(line, 1, true);
                    }
                } else {
                    data.padding = matched + i;
                }
                data.marker_offset = self.indent;
                let need_new_list = match &self.nodes[*container].kind {
                    Kind::List(ld) => !lists_match(ld, &data),
                    _ => true,
                };
                if need_new_list {
                    *container = self.add_child(*container, Kind::List(data));
                }
                *container = self.add_child(*container, Kind::Item(data));
            } else if indented && !maybe_lazy && !self.blank {
                self.advance_offset(line, CODE_INDENT, true);
                *container = self.add_child(
                    *container,
                    Kind::CodeBlock {
                        fenced: false,
                        fence_char: 0,
                        fence_length: 0,
                        fence_offset: 0,
                        info: String::new(),
                    },
                );
            } else {
                break;
            }
            if matches!(
                self.nodes[*container].kind,
                Kind::Paragraph | Kind::Heading { .. } | Kind::CodeBlock { .. }
            ) {
                break;
            }
            maybe_lazy = false;
        }
    }

    fn scan_thematic_break(&mut self, line: &[u8], pos: usize) -> bool {
        let c = peek(line, pos);
        if c != b'*' && c != b'_' && c != b'-' {
            self.thematic_break_kill_pos = pos;
            return false;
        }
        let mut count = 0;
        let mut i = pos;
        loop {
            let d = peek(line, i);
            if d == c {
                count += 1;
            } else if d == b' ' || d == b'\t' {
            } else {
                break;
            }
            i += 1;
        }
        if count >= 3 && is_line_end(peek(line, i)) {
            true
        } else {
            self.thematic_break_kill_pos = i;
            false
        }
    }

    fn add_text_to_container(&mut self, mut container: usize, last_matched: usize, line: &[u8]) {
        self.find_first_nonspace(line);
        if self.blank {
            if let Some(&lc) = self.nodes[container].children.last() {
                self.nodes[lc].last_line_blank = true;
            }
        }
        let ckind = self.nodes[container].kind.clone();
        let last_line_blank = self.blank
            && !matches!(ckind, Kind::BlockQuote | Kind::Heading { .. } | Kind::ThematicBreak)
            && !matches!(ckind, Kind::CodeBlock { fenced: true, .. })
            && !(matches!(ckind, Kind::Item(_))
                && self.nodes[container].children.is_empty()
                && self.nodes[container].start_line == self.line_number);
        self.nodes[container].last_line_blank = last_line_blank;
        let mut tmp = container;
        while let Some(p) = self.nodes[tmp].parent {
            self.nodes[p].last_line_blank = false;
            tmp = p;
        }

        if self.current != last_matched
            && container == last_matched
            && !self.blank
            && matches!(self.nodes[self.current].kind, Kind::Paragraph)
        {
            let cur = self.current;
            self.add_line(cur, line);
        } else {
            while self.current != last_matched {
                self.current = self.finalize(self.current);
            }
            match self.nodes[container].kind.clone() {
                Kind::CodeBlock { .. } => {
                    self.add_line(container, line);
                }
                Kind::HtmlBlock { html_type } => {
                    self.add_line(container, line);
                    let rest = &line[self.first_nonspace.min(line.len())..];
                    let ends = match html_type {
                        1 => html_end_1(rest),
                        2 => contains(rest, b"-->"),
                        3 => contains(rest, b"?>"),
                        4 => contains(rest, b">"),
                        5 => contains(rest, b"]]>"),
                        _ => false,
                    };
                    if ends {
                        container = self.finalize(container);
                    }
                }
                _ => {
                    if self.blank {
                        // nothing
                    } else if matches!(self.nodes[container].kind, Kind::Paragraph | Kind::Heading { .. }) {
                        let mut line_owned;
                        let mut l: &[u8] = line;
                        if let Kind::Heading { setext: false, .. } = self.nodes[container].kind {
                            line_owned = line.to_vec();
                            chop_trailing_hashtags(&mut line_owned, self.first_nonspace);
                            l = &line_owned;
                            let n = self.first_nonspace - self.offset;
                            self.advance_offset(l, n, false);
                            self.add_line(container, l);
                            let _ = &mut line_owned;
                        } else {
                            // Paragraph continuation: keep leading whitespace.
                            self.add_line(container, l);
                        }
                    } else {
                        container = self.add_child(container, Kind::Paragraph);
                        let n = self.first_nonspace - self.offset;
                        self.advance_offset(line, n, false);
                        self.add_line(container, line);
                    }
                }
            }
            self.current = container;
        }
    }
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w == needle)
}

fn html_end_1(rest: &[u8]) -> bool {
    let lower: Vec<u8> = rest.iter().map(|c| c.to_ascii_lowercase()).collect();
    contains(&lower, b"</script>")
        || contains(&lower, b"</pre>")
        || contains(&lower, b"</style>")
        || contains(&lower, b"</textarea>")
}

fn chop_trailing_hashtags(line: &mut Vec<u8>, first_nonspace: usize) {
    // remove trailing whitespace
    let mut n = line.len();
    while n > first_nonspace && (line[n - 1] == b' ' || line[n - 1] == b'\t') {
        n -= 1;
    }
    let orig_n = n;
    // if string ends in space followed by #s, remove these:
    while n > first_nonspace && line[n - 1] == b'#' {
        n -= 1;
    }
    if n != orig_n {
        if n > first_nonspace && (line[n - 1] == b' ' || line[n - 1] == b'\t') {
            line.truncate(n);
            // trim trailing whitespace
            while let Some(&c) = line.last() {
                if c == b' ' || c == b'\t' {
                    line.pop();
                } else {
                    break;
                }
            }
        } else if n == first_nonspace {
            line.truncate(n);
        } else {
            line.truncate(orig_n);
        }
    } else {
        line.truncate(orig_n);
    }
}

fn lists_match(a: &ListData, b: &ListData) -> bool {
    a.list_type == b.list_type && a.delimiter == b.delimiter && a.bullet_char == b.bullet_char
}

fn scan_atx_heading_start(line: &[u8], pos: usize) -> Option<usize> {
    let mut i = pos;
    let mut n = 0;
    while peek(line, i) == b'#' {
        n += 1;
        i += 1;
    }
    if n == 0 || n > 6 {
        return None;
    }
    let c = peek(line, i);
    if is_line_end(c) {
        return Some(i - pos);
    }
    if c == b' ' || c == b'\t' {
        while is_space_or_tab(peek(line, i)) {
            i += 1;
        }
        return Some(i - pos);
    }
    None
}

fn scan_open_code_fence(line: &[u8], pos: usize) -> Option<usize> {
    let c = peek(line, pos);
    if c != b'`' && c != b'~' {
        return None;
    }
    let mut i = pos;
    while peek(line, i) == c {
        i += 1;
    }
    let n = i - pos;
    if n < 3 {
        return None;
    }
    if c == b'`' {
        // info string may not contain backticks
        if line[i.min(line.len())..].contains(&b'`') {
            return None;
        }
    }
    Some(n)
}

fn scan_close_code_fence(line: &[u8], pos: usize) -> usize {
    let c = peek(line, pos);
    let mut i = pos;
    while peek(line, i) == c {
        i += 1;
    }
    let n = i - pos;
    if n < 3 {
        return 0;
    }
    let mut j = i;
    while is_space_or_tab(peek(line, j)) {
        j += 1;
    }
    if is_line_end(peek(line, j)) {
        n
    } else {
        0
    }
}

fn scan_setext_heading_line(line: &[u8], pos: usize) -> Option<u8> {
    let c = peek(line, pos);
    if c != b'=' && c != b'-' {
        return None;
    }
    let mut i = pos;
    while peek(line, i) == c {
        i += 1;
    }
    while is_space_or_tab(peek(line, i)) {
        i += 1;
    }
    if is_line_end(peek(line, i)) {
        Some(if c == b'=' { 1 } else { 2 })
    } else {
        None
    }
}

fn parse_list_marker(line: &[u8], pos: usize, interrupts_paragraph: bool) -> Option<(usize, ListData)> {
    let c = peek(line, pos);
    let start_pos = pos;
    let mut p = pos;
    if c == b'*' || c == b'-' || c == b'+' {
        p += 1;
        let d = peek(line, p);
        if !(is_line_end(d) || d == b' ' || d == b'\t') {
            return None;
        }
        if interrupts_paragraph {
            let mut i = p;
            while is_space_or_tab(peek(line, i)) {
                i += 1;
            }
            if is_line_end(peek(line, i)) {
                return None;
            }
        }
        Some((
            p - start_pos,
            ListData {
                list_type: ListType::Bullet,
                marker_offset: 0,
                padding: 0,
                start: 0,
                delimiter: 0,
                bullet_char: c,
                tight: false,
            },
        ))
    } else if c.is_ascii_digit() {
        let mut start: u64 = 0;
        let mut digits = 0;
        loop {
            start = start * 10 + (peek(line, p) - b'0') as u64;
            p += 1;
            digits += 1;
            if !(digits < 9 && peek(line, p).is_ascii_digit()) {
                break;
            }
        }
        if interrupts_paragraph && start != 1 {
            return None;
        }
        let d = peek(line, p);
        if d == b'.' || d == b')' {
            p += 1;
            let e = peek(line, p);
            if !(is_line_end(e) || e == b' ' || e == b'\t') {
                return None;
            }
            if interrupts_paragraph {
                let mut i = p;
                while is_space_or_tab(peek(line, i)) {
                    i += 1;
                }
                if is_line_end(peek(line, i)) {
                    return None;
                }
            }
            Some((
                p - start_pos,
                ListData {
                    list_type: ListType::Ordered,
                    marker_offset: 0,
                    padding: 0,
                    start,
                    delimiter: d,
                    bullet_char: 0,
                    tight: false,
                },
            ))
        } else {
            None
        }
    } else {
        None
    }
}

const BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center",
    "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset",
    "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5",
    "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link", "main", "menu",
    "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param", "search", "section",
    "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title", "tr", "track", "ul",
];

fn scan_html_block_start(line: &[u8], pos: usize, allow7: bool) -> Option<u8> {
    if peek(line, pos) != b'<' {
        return None;
    }
    let rest = &line[pos..];
    let lower: Vec<u8> = rest.iter().map(|c| c.to_ascii_lowercase()).collect();
    // type 1
    for tag in ["script", "pre", "style", "textarea"] {
        let t = tag.as_bytes();
        if lower.len() > t.len() && &lower[1..1 + t.len()] == t {
            let c = peek(&lower, 1 + t.len());
            if c == 0 || c == b' ' || c == b'\t' || c == b'>' {
                return Some(1);
            }
        } else if lower.len() == 1 + t.len() && &lower[1..] == t {
            return Some(1);
        }
    }
    if lower.starts_with(b"<!--") {
        return Some(2);
    }
    if lower.starts_with(b"<?") {
        return Some(3);
    }
    if lower.len() >= 3 && lower[1] == b'!' && lower[2].is_ascii_alphabetic() {
        return Some(4);
    }
    if rest.starts_with(b"<![CDATA[") {
        return Some(5);
    }
    // type 6
    let mut i = 1;
    if peek(&lower, i) == b'/' {
        i += 1;
    }
    let ts = i;
    while peek(&lower, i).is_ascii_alphanumeric() {
        i += 1;
    }
    if i > ts {
        let name = std::str::from_utf8(&lower[ts..i]).unwrap_or("");
        if BLOCK_TAGS.contains(&name) {
            let c = peek(&lower, i);
            if c == 0 || c == b' ' || c == b'\t' || c == b'>' || (c == b'/' && peek(&lower, i + 1) == b'>') {
                return Some(6);
            }
        }
    }
    if allow7 {
        let s = String::from_utf8_lossy(rest).to_string();
        let chars: Vec<char> = s.chars().collect();
        let n = super::inlines::scan_open_tag(&chars, 0)
            .or_else(|| super::inlines::scan_closing_tag(&chars, 0));
        if let Some(end) = n {
            // tag name must not be script/style/pre/textarea for open tags (handled by type1)
            if chars[end..].iter().all(|&c| c == ' ' || c == '\t') {
                return Some(7);
            }
        }
    }
    None
}

/// Parse a link reference definition starting at `pos` ('[').
fn parse_reference(chars: &[char], pos: usize) -> Option<(String, String, String, usize)> {
    use super::inlines::{parse_link_destination, parse_link_label, parse_link_title};
    let (label, mut p) = parse_link_label(chars, pos)?;
    if p >= chars.len() || chars[p] != ':' {
        return None;
    }
    p += 1;
    // spnl
    p = skip_spnl(chars, p);
    let (dest, p2) = parse_link_destination(chars, p)?;
    if p2 == p && !(p < chars.len() && chars[p] == '<') {
        // empty destination not allowed unless <>
        return None;
    }
    let mut p = p2;
    let before_title = p;
    let p_ws = skip_spnl(chars, p);
    let mut title = String::new();
    let mut have_title = false;
    if p_ws != p {
        if let Some((t, p3)) = parse_link_title(chars, p_ws) {
            title = t;
            p = p3;
            have_title = true;
        }
    }
    // rest of line must be blank
    let check_eol = |mut q: usize| -> Option<usize> {
        while q < chars.len() && (chars[q] == ' ' || chars[q] == '\t') {
            q += 1;
        }
        if q >= chars.len() {
            Some(q)
        } else if chars[q] == '\n' {
            Some(q + 1)
        } else {
            None
        }
    };
    let end = if have_title {
        match check_eol(p) {
            Some(e) => Some(e),
            None => {
                // try without title
                title = String::new();
                check_eol(before_title)
            }
        }
    } else {
        check_eol(before_title)
    };
    let end = end?;
    Some((label, unescape_string(&dest), unescape_string(&title), end))
}

fn skip_spnl(chars: &[char], mut p: usize) -> usize {
    while p < chars.len() && (chars[p] == ' ' || chars[p] == '\t') {
        p += 1;
    }
    if p < chars.len() && chars[p] == '\n' {
        p += 1;
        while p < chars.len() && (chars[p] == ' ' || chars[p] == '\t') {
            p += 1;
        }
    }
    p
}

/// Split a table row into trimmed cell sources.
pub fn split_row(line: &str) -> Vec<String> {
    let s = line.trim();
    let chars: Vec<char> = s.chars().collect();
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut i = 0;
    let start = if chars.first() == Some(&'|') { 1 } else { 0 };
    i += start;
    let mut ended_with_pipe = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() && chars[i + 1] == '|' {
            cur.push('|');
            i += 2;
            ended_with_pipe = false;
            continue;
        }
        if c == '\\' && i + 1 < chars.len() {
            cur.push(c);
            cur.push(chars[i + 1]);
            i += 2;
            ended_with_pipe = false;
            continue;
        }
        if c == '|' {
            cells.push(cur.trim().to_string());
            cur = String::new();
            ended_with_pipe = true;
            i += 1;
            continue;
        }
        ended_with_pipe = false;
        cur.push(c);
        i += 1;
    }
    if !ended_with_pipe || !cur.trim().is_empty() {
        cells.push(cur.trim().to_string());
    }
    cells
}

fn row_has_pipe(line: &str) -> bool {
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' {
            i += 2;
            continue;
        }
        if chars[i] == '|' {
            return true;
        }
        i += 1;
    }
    false
}

fn parse_delim_row(line: &str) -> Option<Vec<Align>> {
    if !line.contains('|') {
        return None;
    }
    let s = line.trim();
    let s = s.strip_prefix('|').unwrap_or(s);
    let s = s.strip_suffix('|').unwrap_or(s);
    let mut aligns = Vec::new();
    for cell in s.split('|') {
        let c = cell.trim();
        let left = c.starts_with(':');
        let right = c.ends_with(':') && c.len() > 1 || (c == ":" && false);
        let inner = c.trim_start_matches(':').trim_end_matches(':');
        if inner.is_empty() || !inner.chars().all(|ch| ch == '-') {
            return None;
        }
        if c.len() >= 2 && c.starts_with(':') && c.ends_with(':') {
            aligns.push(Align::Center);
        } else if left {
            aligns.push(Align::Left);
        } else if right {
            aligns.push(Align::Right);
        } else {
            aligns.push(Align::None);
        }
    }
    Some(aligns)
}

fn table_head(head: &str, delim: &str) -> Option<(Vec<String>, Vec<Align>)> {
    if !row_has_pipe(head) {
        return None;
    }
    let aligns = parse_delim_row(delim)?;
    let header = split_row(head);
    if header.len() != aligns.len() {
        return None;
    }
    Some((header, aligns))
}

fn paragraph_has_table(content: &str) -> bool {
    let lines: Vec<&str> = content.trim_end_matches('\n').split('\n').collect();
    for i in 0..lines.len().saturating_sub(1) {
        if table_head(lines[i], lines[i + 1]).is_some() {
            return true;
        }
    }
    false
}

pub fn parse_document(src: &str) -> Document {
    let mut p = Parser::new();
    let mut lines: Vec<&str> = src.split('\n').collect();
    if src.ends_with('\n') {
        lines.pop();
    }
    for l in lines {
        let l = l.strip_suffix('\r').unwrap_or(l);
        p.process_line(l);
    }
    // finalize all
    while p.current != 0 {
        p.current = p.finalize(p.current);
    }
    p.finalize(0);
    Document { nodes: p.nodes, refmap: p.refmap }
}
