//! Inline parsing (CommonMark), with pulldown-cmark style math spans.

use super::util::*;
use std::collections::HashMap;

#[derive(Clone, Debug)]
pub enum IKind {
    Root,
    Text(String),
    Code(String),
    Math { display: bool, content: String },
    Html(String),
    SoftBreak,
    HardBreak,
    Emph,
    Strong,
    Link { dest: String, title: String, email: bool },
    Image { dest: String, title: String },
}

#[derive(Clone, Debug)]
pub struct INode {
    pub kind: IKind,
    pub parent: Option<usize>,
    pub first_child: Option<usize>,
    pub last_child: Option<usize>,
    pub prev: Option<usize>,
    pub next: Option<usize>,
}

pub struct Inlines {
    pub nodes: Vec<INode>,
}

impl Inlines {
    fn new() -> Inlines {
        Inlines {
            nodes: vec![INode {
                kind: IKind::Root,
                parent: None,
                first_child: None,
                last_child: None,
                prev: None,
                next: None,
            }],
        }
    }

    fn make(&mut self, kind: IKind) -> usize {
        self.nodes.push(INode { kind, parent: None, first_child: None, last_child: None, prev: None, next: None });
        self.nodes.len() - 1
    }

    fn append_child(&mut self, parent: usize, child: usize) {
        self.unlink(child);
        self.nodes[child].parent = Some(parent);
        match self.nodes[parent].last_child {
            Some(l) => {
                self.nodes[l].next = Some(child);
                self.nodes[child].prev = Some(l);
            }
            None => {
                self.nodes[parent].first_child = Some(child);
            }
        }
        self.nodes[parent].last_child = Some(child);
    }

    fn insert_after(&mut self, node: usize, new: usize) {
        self.unlink(new);
        let parent = self.nodes[node].parent;
        let next = self.nodes[node].next;
        self.nodes[new].parent = parent;
        self.nodes[new].prev = Some(node);
        self.nodes[new].next = next;
        self.nodes[node].next = Some(new);
        match next {
            Some(n) => self.nodes[n].prev = Some(new),
            None => {
                if let Some(p) = parent {
                    self.nodes[p].last_child = Some(new);
                }
            }
        }
    }

    fn unlink(&mut self, node: usize) {
        let prev = self.nodes[node].prev;
        let next = self.nodes[node].next;
        let parent = self.nodes[node].parent;
        if let Some(p) = prev {
            self.nodes[p].next = next;
        } else if let Some(par) = parent {
            if self.nodes[par].first_child == Some(node) {
                self.nodes[par].first_child = next;
            }
        }
        if let Some(n) = next {
            self.nodes[n].prev = prev;
        } else if let Some(par) = parent {
            if self.nodes[par].last_child == Some(node) {
                self.nodes[par].last_child = prev;
            }
        }
        self.nodes[node].prev = None;
        self.nodes[node].next = None;
        self.nodes[node].parent = None;
    }

    pub fn children(&self, node: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut c = self.nodes[node].first_child;
        while let Some(x) = c {
            out.push(x);
            c = self.nodes[x].next;
        }
        out
    }
}

struct Delim {
    node: usize,
    ch: char,
    count: usize,
    orig: usize,
    can_open: bool,
    can_close: bool,
    position: usize,
}

struct Bracket {
    node: usize,
    image: bool,
    active: bool,
    bracket_after: bool,
    index: usize,
    delim_bottom: usize,
}

struct Subject<'a> {
    chars: Vec<char>,
    pos: usize,
    refmap: &'a HashMap<String, (String, String)>,
    tree: Inlines,
    delims: Vec<Delim>,
    brackets: Vec<Bracket>,
    escaped: Vec<bool>,
    brace: Vec<i64>,
    delim_counter: usize,
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0c' || c == '\x0b'
}

pub fn parse_inlines(text: &str, refmap: &HashMap<String, (String, String)>) -> Inlines {
    let trimmed = text.trim_end_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r');
    let chars: Vec<char> = trimmed.chars().collect();
    let n = chars.len();
    // Precompute escapes and brace context for math.
    let mut escaped = vec![false; n];
    let mut brace = vec![0i64; n];
    let mut depth: i64 = 0;
    let mut i = 0;
    while i < n {
        brace[i] = depth;
        if chars[i] == '\\' && i + 1 < n && is_ascii_punct(chars[i + 1]) {
            escaped[i + 1] = true;
            if i + 1 < n {
                brace[i + 1] = depth;
            }
            i += 2;
            continue;
        }
        if chars[i] == '{' {
            depth += 1;
        } else if chars[i] == '}' {
            depth -= 1;
        }
        i += 1;
    }
    let mut subj = Subject {
        chars,
        pos: 0,
        refmap,
        tree: Inlines::new(),
        delims: Vec::new(),
        brackets: Vec::new(),
        escaped,
        brace,
        delim_counter: 0,
    };
    subj.parse_all();
    subj.tree
}

impl<'a> Subject<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, p: usize) -> Option<char> {
        self.chars.get(p).copied()
    }

    fn add_text(&mut self, s: String) -> usize {
        let n = self.tree.make(IKind::Text(s));
        self.tree.append_child(0, n);
        n
    }

    fn add(&mut self, kind: IKind) -> usize {
        let n = self.tree.make(kind);
        self.tree.append_child(0, n);
        n
    }

    fn parse_all(&mut self) {
        while self.pos < self.chars.len() {
            self.parse_inline();
        }
        self.process_emphasis(0);
    }

    fn parse_inline(&mut self) {
        let c = self.chars[self.pos];
        match c {
            '\n' => self.handle_newline(),
            '`' => self.handle_backticks(),
            '\\' => self.handle_backslash(),
            '&' => self.handle_entity(),
            '<' => self.handle_pointy(),
            '*' | '_' => self.handle_delim(c),
            '[' => {
                self.pos += 1;
                let node = self.add_text("[".to_string());
                self.push_bracket(node, false);
            }
            '!' => {
                if self.peek_at(self.pos + 1) == Some('[') {
                    self.pos += 2;
                    let node = self.add_text("![".to_string());
                    self.push_bracket(node, true);
                } else {
                    self.pos += 1;
                    self.add_text("!".to_string());
                }
            }
            ']' => self.handle_close_bracket(),
            '$' => self.handle_dollar(),
            _ => {
                let start = self.pos;
                while self.pos < self.chars.len() {
                    let d = self.chars[self.pos];
                    if matches!(d, '\n' | '`' | '\\' | '&' | '<' | '*' | '_' | '[' | ']' | '!' | '$') {
                        break;
                    }
                    self.pos += 1;
                }
                let mut s: String = self.chars[start..self.pos].iter().collect();
                // strip trailing whitespace before newline (handled in newline)
                if self.peek() == Some('\n') {
                    // keep, newline handler trims
                }
                if s.is_empty() {
                    s = String::new();
                }
                self.add_text(s);
            }
        }
    }

    fn handle_newline(&mut self) {
        let nlpos = self.pos;
        self.pos += 1;
        let hard = nlpos >= 2 && self.chars[nlpos - 1] == ' ' && self.chars[nlpos - 2] == ' ';
        // trim trailing whitespace of last text node
        if let Some(last) = self.tree.nodes[0].last_child {
            if let IKind::Text(t) = &mut self.tree.nodes[last].kind {
                let trimmed = t.trim_end_matches(|c: char| c == ' ' || c == '\t').to_string();
                *t = trimmed;
            }
        }
        if hard {
            self.add(IKind::HardBreak);
        } else {
            self.add(IKind::SoftBreak);
        }
        // skip leading spaces on next line
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn handle_backslash(&mut self) {
        self.pos += 1;
        match self.peek() {
            Some(c) if is_ascii_punct(c) => {
                self.pos += 1;
                self.add_text(c.to_string());
            }
            Some('\n') => {
                self.pos += 1;
                self.add(IKind::HardBreak);
                while let Some(c) = self.peek() {
                    if c == ' ' || c == '\t' {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
            }
            _ => {
                self.add_text("\\".to_string());
            }
        }
    }

    fn handle_entity(&mut self) {
        if let Some((rep, len)) = parse_entity(&self.chars[self.pos..]) {
            self.pos += len;
            self.add_text(rep);
        } else {
            self.pos += 1;
            self.add_text("&".to_string());
        }
    }

    /// Content of a multi-line raw span: trailing whitespace before each
    /// newline is removed.
    fn raw_span(&self, start: usize, end: usize) -> String {
        let s: String = self.chars[start..end].iter().collect();
        let mut out = String::new();
        let parts: Vec<&str> = s.split('\n').collect();
        for (i, p) in parts.iter().enumerate() {
            if i + 1 < parts.len() {
                out.push_str(p.trim_end_matches(|c: char| c == ' ' || c == '\t'));
                out.push('\n');
            } else {
                out.push_str(p);
            }
        }
        out
    }

    fn handle_backticks(&mut self) {
        let start = self.pos;
        while self.peek() == Some('`') {
            self.pos += 1;
        }
        let ticks = self.pos - start;
        let after_open = self.pos;
        let mut p = self.pos;
        while p < self.chars.len() {
            if self.chars[p] == '`' {
                let rs = p;
                while p < self.chars.len() && self.chars[p] == '`' {
                    p += 1;
                }
                if p - rs == ticks {
                    let raw = self.raw_span(after_open, rs);
                    let contents: String = raw.replace('\n', " ");
                    let literal = if !contents.is_empty()
                        && contents.chars().any(|c| c != ' ')
                        && contents.starts_with(' ')
                        && contents.ends_with(' ')
                    {
                        contents[1..contents.len() - 1].to_string()
                    } else {
                        contents
                    };
                    self.pos = p;
                    self.add(IKind::Code(literal));
                    return;
                }
            } else {
                p += 1;
            }
        }
        self.pos = after_open;
        self.add_text("`".repeat(ticks));
    }

    fn is_dollar(&self, p: usize) -> bool {
        p < self.chars.len() && self.chars[p] == '$' && !self.escaped[p]
    }

    fn handle_dollar(&mut self) {
        let i = self.pos;
        let n = self.chars.len();
        let can_open = match self.peek_at(i + 1) {
            Some(c) => !c.is_whitespace(),
            None => true,
        };
        if !can_open {
            self.pos += 1;
            self.add_text("$".to_string());
            return;
        }
        let display = self.is_dollar(i + 1);
        let ctx = self.brace[i];
        let mut j = if display { i + 2 } else { i + 1 };
        let mut found: Option<usize> = None;
        while j < n {
            if self.is_dollar(j) && self.brace[j] == ctx {
                if display {
                    if self.is_dollar(j + 1) {
                        found = Some(j);
                    }
                } else {
                    let can_close = j > 0 && !self.chars[j - 1].is_whitespace();
                    if can_close {
                        found = Some(j);
                    }
                }
                break;
            }
            j += 1;
        }
        match found {
            Some(j) => {
                let cstart = if display { i + 2 } else { i + 1 };
                let content = self.raw_span(cstart, j);
                self.pos = if display { j + 2 } else { j + 1 };
                self.add(IKind::Math { display, content });
            }
            None => {
                self.pos += 1;
                self.add_text("$".to_string());
            }
        }
    }

    fn handle_pointy(&mut self) {
        // autolink
        if let Some((dest, len, email)) = scan_autolink(&self.chars, self.pos) {
            let text: String = self.chars[self.pos + 1..self.pos + len - 1].iter().collect();
            self.pos += len;
            let link = self.tree.make(IKind::Link { dest: dest.clone(), title: String::new(), email });
            let t = self.tree.make(IKind::Text(text));
            self.tree.append_child(link, t);
            self.tree.append_child(0, link);
            return;
        }
        if let Some(end) = scan_html_inline(&self.chars, self.pos) {
            let raw = self.raw_span(self.pos, end);
            self.pos = end;
            self.add(IKind::Html(raw));
            return;
        }
        self.pos += 1;
        self.add_text("<".to_string());
    }

    fn handle_delim(&mut self, c: char) {
        let start = self.pos;
        while self.peek() == Some(c) {
            self.pos += 1;
        }
        let count = self.pos - start;
        let before = if start == 0 { '\n' } else { self.chars[start - 1] };
        let after = self.peek().unwrap_or('\n');
        let before_ws = is_unicode_whitespace(before);
        let after_ws = is_unicode_whitespace(after);
        let before_p = is_punctuation(before);
        let after_p = is_punctuation(after);
        let left_flanking = !after_ws && (!after_p || before_ws || before_p);
        let right_flanking = !before_ws && (!before_p || after_ws || after_p);
        let (can_open, can_close) = if c == '_' {
            (left_flanking && (!right_flanking || before_p), right_flanking && (!left_flanking || after_p))
        } else {
            (left_flanking, right_flanking)
        };
        let text: String = std::iter::repeat(c).take(count).collect();
        let node = self.add_text(text);
        if can_open || can_close {
            self.delim_counter += 1;
            self.delims.push(Delim {
                node,
                ch: c,
                count,
                orig: count,
                can_open,
                can_close,
                position: self.delim_counter,
            });
        }
    }

    fn push_bracket(&mut self, node: usize, image: bool) {
        if let Some(b) = self.brackets.last_mut() {
            b.bracket_after = true;
        }
        let index = self.pos;
        self.brackets.push(Bracket {
            node,
            image,
            active: true,
            bracket_after: false,
            index,
            delim_bottom: self.delims.len(),
        });
    }

    fn spnl(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.peek() == Some('\n') {
            self.pos += 1;
            while let Some(c) = self.peek() {
                if c == ' ' || c == '\t' {
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
    }

    fn handle_close_bracket(&mut self) {
        self.pos += 1;
        let startpos = self.pos;
        let opener = match self.brackets.last() {
            None => {
                self.add_text("]".to_string());
                return;
            }
            Some(b) => (b.node, b.image, b.active, b.bracket_after, b.index, b.delim_bottom),
        };
        let (onode, is_image, active, bracket_after, oindex, delim_bottom) = opener;
        if !active {
            self.add_text("]".to_string());
            self.brackets.pop();
            return;
        }
        let savepos = self.pos;
        let mut matched = false;
        let mut dest = String::new();
        let mut title = String::new();
        if self.peek() == Some('(') {
            self.pos += 1;
            self.spnl();
            if let Some((d, p)) = parse_link_destination(&self.chars, self.pos) {
                let dest_raw = d;
                self.pos = p;
                let before_title = self.pos;
                self.spnl();
                let mut ok = true;
                if self.pos > 0 && is_ws(self.chars[self.pos - 1]) && self.pos != before_title || (self.pos > before_title) {
                    if let Some((t, p2)) = parse_link_title(&self.chars, self.pos) {
                        title = unescape_string(&t);
                        self.pos = p2;
                    }
                }
                self.spnl();
                if self.peek() == Some(')') {
                    self.pos += 1;
                    matched = true;
                    dest = unescape_string(&dest_raw);
                } else {
                    ok = false;
                }
                if !ok {
                    self.pos = savepos;
                    title = String::new();
                }
            } else {
                self.pos = savepos;
            }
        }
        if !matched {
            let before_label = self.pos;
            let mut reflabel: Option<String> = None;
            let n = match parse_link_label_len(&self.chars, self.pos) {
                Some(n) => n,
                None => 0,
            };
            if n > 2 {
                reflabel = Some(self.chars[before_label + 1..before_label + n - 1].iter().collect());
            } else if !bracket_after {
                reflabel = Some(self.chars[oindex..startpos - 1].iter().collect());
            }
            if n == 0 {
                self.pos = savepos;
            } else {
                self.pos = before_label + n;
            }
            if let Some(lab) = reflabel {
                if lab.chars().count() <= 999 {
                    let norm = normalize_label(&lab);
                    if let Some((d, t)) = self.refmap.get(&norm) {
                        dest = d.clone();
                        title = t.clone();
                        matched = true;
                    }
                }
            }
            if !matched {
                self.pos = savepos;
            }
        }
        if matched {
            let kind = if is_image {
                IKind::Image { dest, title }
            } else {
                IKind::Link { dest, title, email: false }
            };
            let node = self.tree.make(kind);
            let mut tmp = self.tree.nodes[onode].next;
            while let Some(t) = tmp {
                let next = self.tree.nodes[t].next;
                self.tree.append_child(node, t);
                tmp = next;
            }
            self.tree.append_child(0, node);
            self.process_emphasis(delim_bottom);
            self.brackets.pop();
            self.tree.unlink(onode);
            if !is_image {
                for b in self.brackets.iter_mut() {
                    if !b.image {
                        b.active = false;
                    }
                }
            }
        } else {
            self.brackets.pop();
            self.pos = startpos;
            self.add_text("]".to_string());
        }
    }

    fn process_emphasis(&mut self, stack_bottom: usize) {
        // openers_bottom keyed by (char, can_open, orig % 3)
        let mut openers_bottom: HashMap<(char, bool, usize), usize> = HashMap::new();
        let mut ci = stack_bottom;
        while ci < self.delims.len() {
            if !self.delims[ci].can_close {
                ci += 1;
                continue;
            }
            let (cch, ccan_open, corig) = (self.delims[ci].ch, self.delims[ci].can_open, self.delims[ci].orig);
            let key = (cch, ccan_open, corig % 3);
            let bottom = *openers_bottom.get(&key).unwrap_or(&stack_bottom);
            let mut oi_found: Option<usize> = None;
            let mut oi = ci;
            while oi > bottom.max(stack_bottom) {
                oi -= 1;
                let o = &self.delims[oi];
                if o.can_open && o.ch == cch {
                    let odd_match = (ccan_open || o.can_close) && corig % 3 != 0 && (o.orig + corig) % 3 == 0;
                    if !odd_match {
                        oi_found = Some(oi);
                        break;
                    }
                }
            }
            match oi_found {
                Some(oi) => {
                    let use_delims = if self.delims[ci].count >= 2 && self.delims[oi].count >= 2 { 2 } else { 1 };
                    let onode = self.delims[oi].node;
                    let cnode = self.delims[ci].node;
                    self.delims[oi].count -= use_delims;
                    self.delims[ci].count -= use_delims;
                    let oc = self.delims[oi].count;
                    let cc = self.delims[ci].count;
                    if let IKind::Text(t) = &mut self.tree.nodes[onode].kind {
                        let n = t.chars().count() - use_delims;
                        *t = t.chars().take(n).collect();
                    }
                    if let IKind::Text(t) = &mut self.tree.nodes[cnode].kind {
                        let n = t.chars().count() - use_delims;
                        *t = t.chars().take(n).collect();
                    }
                    let emph = self.tree.make(if use_delims == 1 { IKind::Emph } else { IKind::Strong });
                    let mut tmp = self.tree.nodes[onode].next;
                    while let Some(t) = tmp {
                        if t == cnode {
                            break;
                        }
                        let next = self.tree.nodes[t].next;
                        self.tree.append_child(emph, t);
                        tmp = next;
                    }
                    self.tree.insert_after(onode, emph);
                    // remove delimiters between opener and closer
                    self.delims.drain(oi + 1..ci);
                    ci = oi + 1;
                    if oc == 0 {
                        self.tree.unlink(onode);
                        self.delims.remove(oi);
                        ci -= 1;
                    }
                    if cc == 0 {
                        self.tree.unlink(cnode);
                        self.delims.remove(ci);
                    }
                }
                None => {
                    openers_bottom.insert(key, ci);
                    if !ccan_open {
                        self.delims.remove(ci);
                    } else {
                        ci += 1;
                    }
                }
            }
        }
        self.delims.truncate(stack_bottom);
    }
}

/// Scan a link label starting at '['. Returns (label, position after ']').
pub fn parse_link_label(chars: &[char], pos: usize) -> Option<(String, usize)> {
    if pos >= chars.len() || chars[pos] != '[' {
        return None;
    }
    let mut p = pos + 1;
    let mut length = 0;
    while p < chars.len() {
        let c = chars[p];
        if c == '[' {
            return None;
        }
        if c == ']' {
            let label: String = chars[pos + 1..p].iter().collect();
            if label.trim_matches(|c: char| is_unicode_whitespace(c)).is_empty() {
                return None;
            }
            return Some((label, p + 1));
        }
        if c == '\\' {
            p += 1;
            length += 1;
            if p < chars.len() && is_ascii_punct(chars[p]) {
                p += 1;
                length += 1;
            }
        } else {
            p += 1;
            length += 1;
        }
        if length > 999 {
            return None;
        }
    }
    None
}

/// Length of a link label (including brackets) at pos, as used for
/// full/collapsed reference links; label may be empty ("[]").
fn parse_link_label_len(chars: &[char], pos: usize) -> Option<usize> {
    if pos >= chars.len() || chars[pos] != '[' {
        return None;
    }
    let mut p = pos + 1;
    let mut count = 0;
    while p < chars.len() {
        let c = chars[p];
        if c == '\\' && p + 1 < chars.len() {
            p += 2;
            count += 2;
        } else if c == '[' {
            return None;
        } else if c == ']' {
            if count > 999 {
                return None;
            }
            return Some(p + 1 - pos);
        } else {
            p += 1;
            count += 1;
        }
        if count > 1000 {
            return None;
        }
    }
    None
}

/// Parse a link destination at pos. Returns raw (still escaped) destination
/// and new position.
pub fn parse_link_destination(chars: &[char], pos: usize) -> Option<(String, usize)> {
    if pos < chars.len() && chars[pos] == '<' {
        let mut p = pos + 1;
        while p < chars.len() {
            let c = chars[p];
            if c == '\\' && p + 1 < chars.len() && is_ascii_punct(chars[p + 1]) {
                p += 2;
                continue;
            }
            if c == '>' {
                let s: String = chars[pos + 1..p].iter().collect();
                return Some((s, p + 1));
            }
            if c == '<' || c == '\n' {
                return None;
            }
            p += 1;
        }
        return None;
    }
    let mut p = pos;
    let mut parens = 0usize;
    while p < chars.len() {
        let c = chars[p];
        if c == '\\' && p + 1 < chars.len() && is_ascii_punct(chars[p + 1]) {
            p += 2;
            continue;
        }
        if c == '(' {
            parens += 1;
            if parens > 32 {
                return None;
            }
            p += 1;
        } else if c == ')' {
            if parens == 0 {
                break;
            }
            parens -= 1;
            p += 1;
        } else if c == ' ' || c.is_ascii_control() {
            break;
        } else {
            p += 1;
        }
    }
    if parens != 0 {
        return None;
    }
    if p == pos && !(p < chars.len() && chars[p] == ')') {
        return None;
    }
    let s: String = chars[pos..p].iter().collect();
    Some((s, p))
}

/// Parse a link title at pos. Returns raw title content and position after.
pub fn parse_link_title(chars: &[char], pos: usize) -> Option<(String, usize)> {
    if pos >= chars.len() {
        return None;
    }
    let open = chars[pos];
    let close = match open {
        '"' => '"',
        '\'' => '\'',
        '(' => ')',
        _ => return None,
    };
    let mut p = pos + 1;
    while p < chars.len() {
        let c = chars[p];
        if c == '\\' && p + 1 < chars.len() && is_ascii_punct(chars[p + 1]) {
            p += 2;
            continue;
        }
        if c == close {
            let s: String = chars[pos + 1..p].iter().collect();
            return Some((s, p + 1));
        }
        if open == '(' && c == '(' {
            return None;
        }
        p += 1;
    }
    None
}

fn scan_autolink(chars: &[char], pos: usize) -> Option<(String, usize, bool)> {
    // URI autolink
    let mut p = pos + 1;
    if p < chars.len() && chars[p].is_ascii_alphabetic() {
        let s = p;
        p += 1;
        while p < chars.len() && (chars[p].is_ascii_alphanumeric() || matches!(chars[p], '+' | '.' | '-')) {
            p += 1;
        }
        let slen = p - s;
        if (2..=32).contains(&slen) && p < chars.len() && chars[p] == ':' {
            p += 1;
            while p < chars.len() {
                let c = chars[p];
                if c == '>' {
                    let dest: String = chars[pos + 1..p].iter().collect();
                    return Some((dest, p + 1 - pos, false));
                }
                if c == '<' || (c as u32) <= 0x20 {
                    break;
                }
                p += 1;
            }
        }
    }
    // email autolink
    let mut p = pos + 1;
    let s = p;
    while p < chars.len()
        && (chars[p].is_ascii_alphanumeric() || ".!#$%&'*+/=?^_`{|}~-".contains(chars[p]))
    {
        p += 1;
    }
    if p == s || p >= chars.len() || chars[p] != '@' {
        return None;
    }
    p += 1;
    // domain labels
    loop {
        let ls = p;
        if p >= chars.len() || !chars[p].is_ascii_alphanumeric() {
            return None;
        }
        while p < chars.len() && (chars[p].is_ascii_alphanumeric() || chars[p] == '-') {
            p += 1;
        }
        let label = &chars[ls..p];
        if label.len() > 63 || *label.last().unwrap() == '-' {
            return None;
        }
        if p < chars.len() && chars[p] == '.' {
            p += 1;
            continue;
        }
        break;
    }
    if p < chars.len() && chars[p] == '>' {
        let dest: String = chars[pos + 1..p].iter().collect();
        return Some((dest, p + 1 - pos, true));
    }
    None
}

fn is_tag_name_start(c: char) -> bool {
    c.is_ascii_alphabetic()
}

fn skip_ws(chars: &[char], mut p: usize) -> usize {
    while p < chars.len() && matches!(chars[p], ' ' | '\t' | '\n' | '\r' | '\x0c') {
        p += 1;
    }
    p
}

/// Scan an HTML open tag at pos; returns end position.
pub fn scan_open_tag(chars: &[char], pos: usize) -> Option<usize> {
    let mut p = pos;
    if p >= chars.len() || chars[p] != '<' {
        return None;
    }
    p += 1;
    if p >= chars.len() || !is_tag_name_start(chars[p]) {
        return None;
    }
    while p < chars.len() && (chars[p].is_ascii_alphanumeric() || chars[p] == '-') {
        p += 1;
    }
    loop {
        // attribute: whitespace + name + optional value
        let ws_end = skip_ws(chars, p);
        if ws_end > p && ws_end < chars.len() && (chars[ws_end].is_ascii_alphabetic() || chars[ws_end] == '_' || chars[ws_end] == ':') {
            let mut q = ws_end + 1;
            while q < chars.len() && (chars[q].is_ascii_alphanumeric() || matches!(chars[q], '_' | '.' | ':' | '-')) {
                q += 1;
            }
            // optional value spec
            let q2 = skip_ws(chars, q);
            if q2 < chars.len() && chars[q2] == '=' {
                let q3 = skip_ws(chars, q2 + 1);
                if q3 >= chars.len() {
                    return None;
                }
                let c = chars[q3];
                if c == '"' || c == '\'' {
                    let mut r = q3 + 1;
                    while r < chars.len() && chars[r] != c {
                        r += 1;
                    }
                    if r >= chars.len() {
                        return None;
                    }
                    p = r + 1;
                } else {
                    let mut r = q3;
                    while r < chars.len() && !matches!(chars[r], '"' | '\'' | '=' | '<' | '>' | '`') && (chars[r] as u32) > 0x20 {
                        r += 1;
                    }
                    if r == q3 {
                        return None;
                    }
                    p = r;
                }
            } else {
                p = q;
            }
            continue;
        }
        break;
    }
    let p = skip_ws(chars, p);
    if p < chars.len() && chars[p] == '>' {
        return Some(p + 1);
    }
    if p + 1 < chars.len() && chars[p] == '/' && chars[p + 1] == '>' {
        return Some(p + 2);
    }
    None
}

pub fn scan_closing_tag(chars: &[char], pos: usize) -> Option<usize> {
    let mut p = pos;
    if p + 1 >= chars.len() || chars[p] != '<' || chars[p + 1] != '/' {
        return None;
    }
    p += 2;
    if p >= chars.len() || !is_tag_name_start(chars[p]) {
        return None;
    }
    while p < chars.len() && (chars[p].is_ascii_alphanumeric() || chars[p] == '-') {
        p += 1;
    }
    let p = skip_ws(chars, p);
    if p < chars.len() && chars[p] == '>' {
        Some(p + 1)
    } else {
        None
    }
}

fn starts_with(chars: &[char], pos: usize, s: &str) -> bool {
    let sc: Vec<char> = s.chars().collect();
    pos + sc.len() <= chars.len() && chars[pos..pos + sc.len()] == sc[..]
}

fn find_from(chars: &[char], pos: usize, s: &str) -> Option<usize> {
    let sc: Vec<char> = s.chars().collect();
    let mut p = pos;
    while p + sc.len() <= chars.len() {
        if chars[p..p + sc.len()] == sc[..] {
            return Some(p);
        }
        p += 1;
    }
    None
}

fn scan_html_inline(chars: &[char], pos: usize) -> Option<usize> {
    if let Some(e) = scan_open_tag(chars, pos) {
        return Some(e);
    }
    if let Some(e) = scan_closing_tag(chars, pos) {
        return Some(e);
    }
    if starts_with(chars, pos, "<!--") {
        if starts_with(chars, pos, "<!-->") {
            return Some(pos + 5);
        }
        if starts_with(chars, pos, "<!--->") {
            return Some(pos + 6);
        }
        return find_from(chars, pos + 4, "-->").map(|e| e + 3);
    }
    if starts_with(chars, pos, "<?") {
        return find_from(chars, pos + 2, "?>").map(|e| e + 2);
    }
    if starts_with(chars, pos, "<![CDATA[") {
        return find_from(chars, pos + 9, "]]>").map(|e| e + 3);
    }
    if starts_with(chars, pos, "<!") && pos + 2 < chars.len() && chars[pos + 2].is_ascii_alphabetic() {
        let mut p = pos + 2;
        while p < chars.len() && chars[p] != '>' {
            p += 1;
        }
        if p < chars.len() {
            return Some(p + 1);
        }
        return None;
    }
    None
}
