use super::inlines::{parse_inlines, IKind, Inlines};
use super::util::*;

/// Custom image rendering hook. Returns either a replacement for the
/// destination URL (rendered as a normal <img>), or raw HTML to emit in
/// place of the image start tag (the alt content is then rendered inline).
