                match data.list_type {
                    ListType::Bullet => self.write_nl_prefixed("<ul>\n"),
                    ListType::Ordered => {
                        if data.start == 1 {
                            self.write_nl_prefixed("<ol>\n");
                        } else {
                            let s = format!("<ol start=\"{}\">\n", data.start);
                            self.write_nl_prefixed(&s);
                        }
                    }
                }
                for &c in &node.children {
                    self.block(doc, c, data.tight);
                }
                match data.list_type {
                    ListType::Bullet => self.write("</ul>\n"),
                    ListType::Ordered => self.write("</ol>\n"),
                }
            }
            Kind::Item(_) => {
                self.write_nl_prefixed("<li>");
                for &c in &node.children {
                    self.block(doc, c, tight);
                }
                self.write("</li>\n");
            }
            Kind::Paragraph => {
                let inl = parse_inlines(&node.content, &doc.refmap);
                if tight {
                    self.inlines(&inl, 0);
                } else {
                    self.write_nl_prefixed("<p>");
                    self.inlines(&inl, 0);
                    self.write("</p>\n");
                }
            }
            Kind::Heading { level, .. } => {
                let content = node.content.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r');
                let inl = parse_inlines(content, &doc.refmap);
                let s = format!("<h{}>", level);
                self.write_nl_prefixed(&s);
                self.inlines(&inl, 0);
                self.write(&format!("</h{}>\n", level));
            }
            Kind::ThematicBreak => {
                self.write_nl_prefixed("<hr />\n");
            }
            Kind::CodeBlock { fenced, info, .. } => {
                if !self.end_newline {
                    self.write("\n");
                }
                let lang = if *fenced { info.split(' ').next().unwrap_or("") } else { "" };
