//! Markdown rendering for cards.

use crate::md;
use crate::md::html::{ImageHandler, ImageRender};
use std::path::PathBuf;

pub struct RenderContext {
    pub port: u16,
    pub rel_dir: PathBuf,
}

pub fn image_destinations(src: &str) -> Vec<String> {
    let doc = md::parse(src);
    md::html::image_destinations(&doc)
}

struct CardImages<'a> {
    ctx: &'a RenderContext,
}

fn is_audio(path: &str) -> bool {
    path.ends_with(".mp3") || path.ends_with(".wav") || path.ends_with(".ogg")
}

impl<'a> ImageHandler for CardImages<'a> {
    fn image(&self, dest: &str, title: &str) -> ImageRender {
        let rel = crate::collection::resolve_media(dest, &self.ctx.rel_dir)
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|| dest.to_string());
        let url = format!("http://localhost:{}/file/{}", self.ctx.port, rel);
        if is_audio(dest) {
            ImageRender::RawThenContent(format!(
                "<audio controls src=\"{}\" title=\"{}\"></audio>",
                url, title
            ))
        } else {
            ImageRender::Img(url)
        }
    }
}

pub fn render(src: &str, ctx: &RenderContext) -> String {
    let doc = md::parse(src);
    let handler = CardImages { ctx };
    let opts = md::html::HtmlOptions { images: Some(&handler) };
    md::html::render_html(&doc, &opts)
}
