            IKind::Link { dest, title, email } => {
                let mut s = String::from("<a href=\"");
                if *email {
                    s.push_str("mailto:");
                }
                escape_href(&mut s, dest);
                if !title.is_empty() {
                    s.push_str("\" title=\"");
                    escape_html(&mut s, title);
                }
                s.push_str("\">");
                self.write(&s);
                self.inlines(inl, n);
                self.write("</a>");
            }
            IKind::Image { dest, title } => {
                let mode = match self.opts.images {
                    Some(h) => h.image(dest, title),
                    None => ImageRender::Img(dest.clone()),
                };
                match mode {
                    ImageRender::Img(url) => {
                        let mut s = String::from("<img src=\"");
                        escape_href(&mut s, &url);
                        s.push_str("\" alt=\"");
                        self.write(&s);
                        let mut alt = String::new();
                        raw_text(inl, n, &mut alt);
                        self.out.push_str(&alt);
                        let mut s = String::new();
                        if !title.is_empty() {
                            s.push_str("\" title=\"");
                            escape_html(&mut s, title);
                        }
                        s.push_str("\" />");
                        self.write(&s);
                    }
                    ImageRender::RawThenContent(html) => {
                        self.write(&html);
                        self.inlines(inl, n);
                    }
                }
            }
        }
    }
}

fn raw_text(inl: &Inlines, parent: usize, out: &mut String) {
    let mut c = inl.nodes[parent].first_child;
    while let Some(n) = c {
        match &inl.nodes[n].kind {
            IKind::Text(t) | IKind::Code(t) | IKind::Html(t) => escape_html(out, t),
            IKind::Math { display, content } => {
                let d = if *display { "$$" } else { "$" };
                out.push_str(d);
                escape_html(out, content);
                out.push_str(d);
            }
            IKind::SoftBreak | IKind::HardBreak => out.push(' '),
            _ => raw_text(inl, n, out),
        }
        c = inl.nodes[n].next;
    }
}

pub fn render_html(doc: &Document, opts: &HtmlOptions) -> String {
    let mut w = Writer { out: String::new(), end_newline: true, opts };
    w.block(doc, doc.root(), false);
    w.out
}

/// Collect image destinations in document order.
pub fn image_destinations(doc: &Document) -> Vec<String> {
    let mut out = Vec::new();
    collect_images_block(doc, doc.root(), &mut out);
    out
}

fn collect_images_block(doc: &Document, n: usize, out: &mut Vec<String>) {
    let node = &doc.nodes[n];
    match &node.kind {
        Kind::Paragraph => {
            let inl = parse_inlines(&node.content, &doc.refmap);
            collect_images_inl(&inl, 0, out);
        }
        Kind::Heading { .. } => {
            let content = node.content.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r');
            let inl = parse_inlines(content, &doc.refmap);
            collect_images_inl(&inl, 0, out);
        }
        Kind::Table { header, rows, .. } => {
            for cell in header.iter().chain(rows.iter().flatten()) {
                let inl = parse_inlines(cell, &doc.refmap);
                collect_images_inl(&inl, 0, out);
            }
        }
        _ => {
            for &c in &node.children {
                collect_images_block(doc, c, out);
            }
        }
    }
}

fn collect_images_inl(inl: &Inlines, parent: usize, out: &mut Vec<String>) {
    let mut c = inl.nodes[parent].first_child;
    while let Some(n) = c {
        if let IKind::Image { dest, .. } = &inl.nodes[n].kind {
            out.push(dest.clone());
        }
        collect_images_inl(inl, n, out);
        c = inl.nodes[n].next;
    }
}
